comms.text:
@1 וּמַלִיל משֶׁה עִם רֵישֵׁי שִׁבְטַּיָא לִבְנֵי יִשְׂרָאֵל לְמֵימָר דֵין פִּתְגָמָא דִי פַקֵיד יְיָ:
@2 גְבַר אֲרֵי יִדַר נְדַר קֳדָם יְיָ אוֹ יְקַיֵים קְיַם לְמֵיסַר אִסַר עַל נַפְשֵׁיהּ לָא יְבַטֵל פִּתְגָמֵיהּ כְּכָל דִי יִפּוֹק מִפּוּמֵיה יַעֲבֵּד:
@3 וְאִתְּתָא אֲרֵי תִדַר נְדַר קֳדָם יְיָ וְתֵיסַר אִסָר בְּבֵית אֲבוּהָא בְּרַבְיוּתָהָא:
@4 וְיִשְׁמַע אֲבוּהָא יָת נִדְרָהּ וְאֵסָרָהּ דִי אֲסָרַת עַל נַפְשָׁהּ וְיִשְׁתּוֹק לָהּ אֲבוּהָא וִיקוּמוּן כָּל נִדְרָהָא וְכָל אֱסָרֵי דִי אֲסָרַת עַל נַפְשָׁהּ יְקוּמוּן:
@5 וְאִם אַעְדֵי אָבוּהָא יָתַהּ בְּיוֹמָא דִשְׁמַע כָּל נִדְרָהָא וֶאֱסָרָהָא דִי אֲסָרַת עַל נַפְשָׁהּ לָא יְקוּמוּן וּמִן קֳדָם יְיָ יִשְׁתְּבֵק לָהּ אֲרֵי אַעְדִי אֲבוּהָא יָתַהּ:
@6 וְאִם מֶהֱוָה תֶהֱוֵי לִגְבַר וְנִדְרָהָא עֲלָהּ אוֹ פֵּירוּשׁ סִפְוָתָהָא דִי אֲסָרַת עַל נַפְשָׁהּ:
@7 וְיִשְׁמַע בַּעֲלַהּ בְּיוֹמָא דִשְׁמַע וְיִשְׁתּוֹק לַהּ וִיקוּמוּן נִדְרָהָא וֶאֱסָרָהָא דִי אֲסָרַת עַל נַפְשַׁהּ יְקוּמוּן:
@8 וְאִם בְּיוֹמָא דִשְׁמַע בַּעֲלַהּ אַעְדִי יָתַהּ וִיבַטֵּל יָת נִדְרָהָא דִי עֲלַהּ וְיָת פֵּירוּשׁ סִפְוָתָהָא דִי אֲסָרַת עַל נַפְשַׁהּ וּמִן קֳדָם יְיָ יִשְׁתְּבֵק לַהּ:
@9 וּנְדַר אַרְמְלָא וּמְתַרְכָא כֹּל דִי אֲסָרַת עַל נַפְשַׁהּ יְקוּם עֲלַהּ:
@10 וְאִם בֵּית בַּעֲלַהּ נְדָרַת אוֹ אֲסָרַת אִסַר עַל נַפְשַׁהּ בְּקִיוּם:
@11 וְיִשְׁמַע בַּעֲלַהּ וְיִשְׁתּוֹק לַהּ לָא אַעֲדֵי יָתַהּ וִיקוּמוּן כָּל נִדְרָהָא וְכָל אֱםָרֵי דִי אֲסָרַת עַל נַפְשַׁהּ יְקוּמוּן:
@12 וְאִם בַּטָלָא יְבַטֵל יָתְהוֹן בַּעֲלַהּ בְּיוֹמָא דִשְׁמַע כָּל אַפָּקוּת סִפְוָתָהָא לְנִדְרָהָא וּלְאִסַר נַפְשַׁהּ לָא יְקוּמוּן בַּעֲלַהּ בְּטֵלִינוּן וּמִן קֳדָם יְיָ יִשְׁתְּבֵק לַהּ:
@13 כָּל נְדַר וְכָל קִיוּמַת אִסַר לְסַגָפָא נְפָשׁ בַּעֲלַהּ יְקַיְמִינוּן וּבַעֲלַהּ יְבַטְלִינוּן:
@14 וְאִם מִשְׁתַּק יִשְׁתּוֹק לַהּ בַּעֲלַהּ מִיוֹם לְיוֹם וִיקַיֵים יָת כָּל נִדְרָהָא אוֹ יָת כָּל אֱסָרָהָא דִי עֲלָהּ קַיֵים יָתְהוֹן אֲרֵי שָׁתֵק לַהּ בְּיוֹמָא דִשְׁמָע:
@15 וְעִם בַּטָלָא יְבַטֵּל יָתְהוֹן בָּתַר דִשְׁמָע וִיקַבַּל יָת חוֹבַהּ:
@16 אִלֵין קְיָמַיָא דִי פַקֵיד יְיָ יָת משֶׁה בֵּין גְבַר לְאִתְּתֵיהּ בֵּין אַבָּא לִבְרַתֵּיהּ בְּרַבְיוּתָהָא בֵּית אָבוּהָא:
@17 וּמַלֵיל יְיָ עִם משֶׁה לְמֵימָר:
@18 אִתְפְּרַע פֻּרְעֲנוּת בְּנֵי יִשְׂרָאֵל מִן מִדְיָנָאֵי בָּתַר כֵּן תִּתְכְּנֵישׁ לְעַמָּךְ:
@19 וּמַלֵיל משֶׁה עִם עַמָא לְמֵימָר זְרִיזוּ מִנְכוֹן גֻבְרִין לְחֵילָא וִיהוֹן עַל מִדְיָן לְמִתַּן פּוּרְעֲנוּת דִין עַמָא דַיְיָ בְּמִדְיָן:
@20 אַלְפָא לְשִׁבְטָא אַלְפָא לְשִׁבְטָּא לְכֹל שִׁבְטַיָא דְיִשְֹׁרָאֵל תְּשַׁלְחוּן לְחֵילָא:
@21 וְאִתְבְּחָרוּ מֵאַלְפַיָא דְיִֹשְׂרָאֵל אַלְפָא לְשִׁבְטָא תְּרֵי עֲֹשַׂר אַלְפִין מְזָרְזֵי חֵילָא:
@22 וּשְׁלַח יָתְהוֹן משֶׁה אַלְפָא לְשִׁבְטָא לְחֵילָא יָתְהוֹן וְיָת פִּינְחָס בַּר אֶלְעָזָר כַּהֲנָא לְחֵילָא וּמָנֵי דְקוּדְשָׁא וַחֲצוֹצְרוֹת יַבֶּבְתָּא בִּידֵיהּ:
@23 וְאִתְחַיָילוּ עַל מִדְיָן כְּמָא דְפַקֵיד יְיָ יָת משֶׁה וּקְטָלוּ כָּל דְכוּרָא:
@24 וְיָת מַלְכֵי מִדְיָן קְטָלוּ עַל קְטִילֵיהוֹן יָת אֱוִי וְיָת רֶקֶם וְיָת צוּר וְיָת חוּר וְיָת רֶבַע חַמְשָׁא מַלְכֵי מִדְיָן וְיָת בִּלְעָם בַּר בְּעוֹר קְטָלוּ בְּחַרְבָּא:
@25 וּשְׁבוֹ בְנֵי יִשְׂרָאֵל יָת נְשֵׁי מִדְיָן וְיָת טַּפְלְהוֹן וְיָת כָּל בְּעִירְהוֹן וְיָת כָּל גֵיתֵיהוֹן וְיָת כָּל נִכְסֵיהוֹן בְּזוֹ:
@26 וְיָת כָּל קִרְוֵיהוֹן בְּמוֹתְבָנֵיהוֹן וְיָת כָּל בֵּית סִגְדַתְהוֹן אוֹקִידוּ בְּנוּרָא:
@27 וּנְסִיבוּ יָת כָּל עֲדָאָה וְיָת כָּל דְבַרְתָּא בֶּאֱנָשָׁא וּבִבְעִירָא:
@28 וְאַיתִיוּ לְוָת משֶׁה וּלְוָת אֶלְעָזָר כַּהֲנָא וּלְוָת כְּנִשְׁתָּא דִבְנֵי יִשְׂרָאֵל יָת שִׁבְיָא וְיָת דְבַרְתָּא וְיָת עֲדָאָה לְמַשְׁרִיתָא לְמֵישְׁרַיָא דְמוֹאָב דִי עַל יַרְדְנָא דִירֵחוֹ:
@29 וּנְפָקוּ משֶׁה וְאֶלְעָזָר כַּהֲנָא וְכָל רַבְרְבֵי כְנִשְׁתָּא לְקֳדָמוּתְהוֹן לְמִבָּרָא לְמַשְׁרִיתָא:
@30 וּרְגֵיז משֶׁה עַל דִמְמַנָן עַל חֵילָא רַבָּנֵי אַלְפִין וְרַבָּנֵי מַאֲוָותָא דְאָתוּ מֵחֵיל קְרָבָא:
@31 וַאֲמַר לְהוֹן משֶׁה הֲקַיֵמְתּוּן כָּל נוּקְבָא:
@32 הָא אִינוּן הֲוָאָה לִבְנֵי יִשְׂרָאֵל בַּעֲצַת בִּלְעָם לְשַׁקָרָא שְׁקָר קֳדָם יְיָ עַל עֵסַק פְּעוֹר וַהֲוַת מוֹתָנָא בִּכְנִשְׁתָּא דַיְיָ:
@33 וּכְעַן קְטוּלוּ כָּל דְכוּרָא בְּטַפְלָא וְכָל אִתְּתָא דִידַעַת גְבַר לְמִשְׁכַּב דְכוּרָא קְטּוּלוּ:
@34 וְכָל טַפְלָא בִנְשַׁיָא דִי לָא יְדָעוּ מִשְׁכַּב דְכוּרָא קַיְימוּ לְכוֹן:
@35 וְאַתּוּן שְׁרוֹ מִבָּרָא לְמַשְׁרִיתָא שַׁבְעָא יוֹמִין כָּל דִי קְטַל נַפְשָׁא וְכֹל דִי קְרַב בְּקָטִילָא תַּדוּן עֲלוֹהִי בְּיוֹמָא תְלִיתָאָה וּבְיוֹמָא שְׁבִיעָאָה אַתּוּן וּשְׁבִיכוֹן:
@36 וְכָל לְבוּשׁ וְכָל מַאן דִמְשַׁךְ וְכָל עוֹבַד מֵעַזֵי וְכָל מַאן דְעָא תַּדוּן עֲלוֹהִי:
@37 וַאֲמַר אֶלְעָזָר כַּהֲנָא לְגַבְרֵי חֵילָא דַאֲתוֹ לִקְרָבָא דָא גְזֵירַת אוֹרַיְיתָא דִי פַקֵיד יְיָ יָת משֶׁה:
@38 בְּרַם יָת דַהֲבָא וְיָת כַסְפָּא יָת נְחָשָׁא יָת פַּרְזְלָא יָת אֲבָצָא וְיָת אֲבָרָא:
@39 כָּל מִדַעַם דְמִתָּעַל בְּנוּרָא תַּעֲבְרוּנֵיהּ בְּנוּרָא וְיִדְכֵּי בְּרַם בְּמֵי אַדָיוּתָא יִתָּדֵי וְכָל דִי לָא מִתָּעַל בְּנוּרָא תַּעַבְרוּנֵיהּ בְּמַיָא:
@40 וּתְחַוְרוּן לְבוּשֵׁיכוֹן בְּיוֹמָא שְׁבִיעָאָה וְתִדְכּוּן וּבָתַר כֵּן תַּעֲלוּן לְמַשְׁרִיתָא:
@41 וַאֲמַר יְיָ לְמשֶׁה לְמֵימָר:
@42 קַבֵּל יָת חוּשְׁבַּן דַבְרַת שִׁבְיָא בֶּאֱנָשָׁא וּבִבְעִירָא אַתְּ וְאֶלְעָזָר כַּהֲנָא וְרֵישֵׁי אֲבָהַת כְּנִשְׁתָּא:
@43 וּתְפַלֵג יָת דְבַרְתָּא בֵּין גַבְרֵי מַגִיחֵי קְרָבָא דְנְפָקוּ לְחֵילָא וּבֵין כָּל כְּנִשְׁתָּא:
@44 וְתַפְרֵשׁ נְסִיבָא קֳדָם יְיָ מִן גַבְרֵי מְגִיחֵי קְרָבָא דִנְפָקוּ לְחֵילָא חָד נַפְשָׁא מֵחֲמֵשׁ מְאָה מִן אֱנָשָׁא וּמִן תּוֹרֵי וּמִן חֲמָרֵי וּמִן עָנָא:
@45 מִפַּלְגוּתְהוֹן תִּסְבוּן וְתִתֵּן לְאֶלְעָזָר כַּהֲנָא אַפְרָשׁוּתָא קֳדָם יְיָ:
@46 וּמִפַּלְגוּת בְּנֵי יִשְׂרָאֵל תִּסַב חָד דְאִתַּחָד מִן חַמְשִׁין מִן אֱנָשָׁא מִן תּוֹרֵי מִן חֲמָרֵי וּמִן עָנָא מִכָּל בְּעִירָא וְתִתֵּן יָתְהוֹן לְלֵוָאֵי נַטְרֵי מַטְרַת מַשְׁכְּנָא דַיְיָ:
@47 וַעֲבַד משֶׁה וְאֶלְעָזָר כַּהֲנָא כְּמָא דִי פַקֵיד יְיָ יָת משֶׁה:
@48 וַהֲוָה דְבַרְתָּא שְׁאָר בִּיזָא דִי בְזוֹ עַמָא דִי נְפָקוּ לְחֵילָא עָנָא שִׁית מְאָה וְשַׁבְעִין וְחַמְשָׁא אַלְפִין:
@49 וְתוֹרֵי שַׁבְעִין וּתְרֵין אַלְפִין:
@50 וַחֲמָרֵי שִׁיתִּין וְחָד אַלְפִין:
@51 וְנַפְשָׁא דֶאֱנָשָׁא מִן נְשַׁיָא דִי לָא יְדָעָא מִשְׁכְּבֵי דְכוּרָא כָּל נַפְשָׁתָא תְּלָתִין וּתְרֵין אַלְפִין:
@52 וַהֲוַת פַלְגוּתָא חוּלַק גוּבְרַיָא דִנְפָקוּ לְחֵילָא מִנְיַן עָנָא תְּלַת מְאָה וּתְלָתִין וּשְׁבַע אַלְפִין וַחֲמֵשׁ מְאָה:
@53 וַהֲוָה נְסִיבָא קֳדָם יְיָ מִן עָנָא שִׁית מְאָה שַׁבְעִין וַחֲמֵשׁ:
@54 וְתוֹרֵי תְּלָתִין וְשִׁתָּא אַלְפִין וּנְסֵיבְהוֹן קֳדָם יְיָ שַׁבְעִין וּתְרֵין:
@55 וַחֲמָרֵי תְּלָתִין אַלְפִין וַחֲמֵשׁ מְאָה וּנְסֵיבְהוֹן קֳדָם יְיָ שִׁתִּין וְחָד:
@56 וְנַפְשָׁא אֱנָשָׁא שִׁתָּא עֲשַׂר אַלְפִין וּנְסֵבְהוֹן קֳדָם יְיָ תְּלָתִין וּתְרֵין נַפְשִׁין:
@57 וִיהַב משֶׁה יָת נְסִיב אַפְרָשׁוּתָא קֳדָם יְיָ לְאֶלְעָזָר כַּהֲנָא כְּמָא דִי פַקֵיד יְיָ יָת משֶׁה:
@58 וּמִפַּלְגוּת בְּנֵי יִשְׂרָאֵל דִי פְּלַג משֶׁה מִן גוּבְרַיָא דִנְפָקוּ לְחֵילָא:
@59 וַהֲוַת פַּלְגוּת כְּנִשְׁתָּא מִן עָנָא תְּלַת מְאָה וּתְלָתִין וְשַׁבְעָא אַלְפִין וַחֲמֵשׁ מְאָה:
@60 וְתוֹרֵי תְּלָתִין וְשִׁתָּא אַלְפִין וַחֲמֵשׁ מְאָה:
@61 וַחֲמָרֵי תְּלָתִין אַלְפִין וַחֲמֵשׁ מְאָה:
@62 וְנַפְשָׁא דְאֱנָשָׁא שִׁתָּא עֲשַׂר אַלְפִין:
@63 וּנְסֵב משֶׁה מִפַּלְגוּת בְּנֵי יִשְׂרָאֵל יָת דְאִתַּחָד חָד מִן חַמְשִׁין מִן אֱנָשָׁא וּמִן בְּעִירָא וִיהַב יָתְהוֹן לְלֵוָאֵי נַטְּרֵי מַטְרַת מַשְׁכְּנָא דַיְיָ כְּמָא דִי פַקֵיד יְיָ יָת משֶׁה:
@64 וּקְרִיבוּ לְוָת משֶׁה דִמְמַנָן עַל אַלְפֵי חֵילָא רַבָּנֵי אַלְפִין וְרַבָּנֵי מַאֲוָתָא:
@65 וַאֲמָרוּ לְמשֶׁה עַבְדָיךְ קַבִּילוּ יָת חוּשְׁבַּן גַבְרֵי מְגִיחֵי קְרָבָא דִי עִמָנָא וְלָא שְׁגָא מִנָנָא אֱנָשׁ:
@66 וְקָרֶבְנָא יָת קוּרְבָּנָא דַיְיָ גְבַר דְאַשְׁכַּח מַאן דִדְהַב שִׁירִין וְשִׁבְּכִין עִזְקָן קַדָשִׁין וּמָחוֹךְ לְכַפָּרָא עַל נַפְשָׁתָנָא קֳדָם יְיָ:
@67 וּנְסֵיב משֶׁה וְאֶלְעָזר כַּהֲנָא יָת דַהֲבָא מִנְהוֹן כָּל מַאן דְעוֹבָדָא:
@68 וַהֲוָה כָּל דְהַב אַפְרָשׁוּתָא דְאַפְרָשׁוּ קֳדָם יְיָ שִׁתָּא עַשֲׂר אַלְפִין שְׁבַע מְאָה וְחַמְשִׁין סִלְעִין מִן רַבָּנֵי אַלְפִין וּמִן רַבָּנֵי מַאֲוָתָא:
@69 גַבְרֵי דְחֵילָא בָּזוּ גְבַר לְנַפְשֵׁיהּ:
@70 וּנְסֵיב משֶׁה וְאֶלְעָזָר כַּהֲנָא יָת דַהֲבָא מִן רַבָּנֵי אַלְפִין וּמַאֲוָתָא וְאַיְתִיאוּ יָתֵיהּ לְמַשְׁכַּן זִמְנָא דָכְרָנָא לִבְנֵי יִשְׂרָאֵל קֳדָם יְיָ:
@71 וּבְעִיר סַגִי הֲוָה לִבְנֵי רְאוּבֵן וְלִבְנֵי גָד תַּקֵּיף לַחֲדָא וַחֲזוֹ יָת אֲרַע יַעְזֵר וְיָת אֲרַע גִּלְעָד וְהָא אַתְרָא אֲתַר כְּשַׁר לְבֵית בְּעִיר:
@72 וַאֲתוֹ בְנֵי גָד וּבְנֵי רְאוּבֵן וַאֲמָרוּ לְמשֶׁה וּלְאֶלְעָזָר כַּהֲנָא וּלְרַבְרְבֵי כְּנִשְׁתָּא לְמֵימָר:
@73 מַכְלֶלְתָּא וּמַלְבֶּשְׁתָּא וְכוּמְרִין וּבֵית נִמְרִין וּבֵית חוּשְׁבָּנָא וּבַעֲלֵי דְבָבָא וְסִימָא וּבֵית קְבוּרְתָּא דְמשֶׁה וּבְעוֹן:
@74 אַרְעָא דִי מְחָא יְיָ יַת יָתְבָהָא קֳדָם כְּנִשְׁתָּא דְיִשְׂרָאֵל אֲרַע כָּשְׁרָא לְבֵית בְּעִיר הִיא וּלְעַבְדָיךְ אִית בְּעִיר:
@75 וַאֲמָרוּ אִם אַשְׁכַּחְנָא רַחֲמִין בְּעֵינָיךְ תִּתְיְהִיב יָת אַרְעָא הָדָא לְעַבְדָךְ לְאַחֲסָנָא לָא תְעַבְרִינָנָא יָת יַרְדְנָא:
@76 וַאֲמַר משֶׁה לִבְנֵי גָד וְלִבְנֵי רְאוּבֵן הַאֲחֵיכוֹן יֵיתוּן לִקְרָבָא וְאַתּוּן תֵּתְבוּן הָכָא:
@77 וּלְמָא תוֹנוּן יָת לִבָּא דִבְנֵי יִשְׂרָאֵל מִלְמֶעֱבַר לְאַרְעָא דִיהַב לְהוֹן יְיָ:
@78 כְּדֵין עֲבָדוּ אֲבָהַתְכוֹן כַּד שְׁלָחִית יָתְהוֹן מֵרְקַם גֵיאָה לְמֶחֱזֵי יָת אַרְעָא:
@79 וּסְלִיקוּ עַד נַחֲלָא דְאַתְכָּלָא וַחֲזוֹ יָת אַרְעָא וְאוֹנִיאוּ יָת לִבָּא דִבְנֵי יִשְׂרָאֵל בְּדִיל דְלָא לְמֵיעַל לְאַרְעָא דִיהַּב לְהוֹן יְיָ:
@80 וּתְקֵיף רוּגְזָא דַיְיָ בְּיוֹמָא הַהוּא וְקַיֵים לְמֵימָר:
@81 אִם יֶחֱזוּן גֻבְרַיָא דִסְלִיקוּ מִמִצְרַיִם מִבַּר עַשְׂרִין שְׁנִין וּלְעֵילָא יָת אַרְעָא דִי קַיֵימִית לְאַבְרָהָם לְיִצְחָק וּלְיַעֲקֹב אֲרֵי לָא אַשְׁלִימוּ בָּתַר דַחַלְתִּי:
@82 אֱלָהֵן כָּלֵב בַּר יְפֻנֶה קְנִזָאָה וִיהוֹשֻׁעַ בַּר נוּן אֲרֵי אַשְׁלִימוּ בָּתַר דַחַלְתָּא דַיְיָ:
@83 וּתְקֵיף רוּגְזָא דַיְיָ בְּיִשְׂרָאֵל וּטְרָדִנוּן בְּמַדְבְּרָא אַרְבְּעִין שְׁנִין עַד דְסַף כָּל דָרָא דְעָבִיד דְבִישׁ קֳדָם יְיָ:
@84 וְהָא קַמְתּוּן חֲלַף אֲבָהַתְכוֹן תַּלְמִידֵי גֻבְרַיָא חַיָבַיָא לְאוֹסָפָא עוֹד עַל תְּקוֹף רוּגְזָא דַיְיָ לְיִשְׂרָאֵל:
@85 אֲרֵי תְתוּבוּן מִבָּתַר דַחַלְתֵּיהּ וְיוֹסִיף עוֹד לְאַחֲרוּתְהוֹן בְּמַדְבְּרָא וּתְחַבְּלוּן לְכָל עַמָא הָדֵין:
@86 וּקְרִיבוּ לְוָתֵיהּ וַאֲמָרוּ חַטְרִין דְעָאן נִבְנֵי לִבְעִירָנָא הָכָא וְקִרְוִין לְטַפְלָנָא:
@87 וַאֲנַחְנָא נִזְדָרֵיז מַבְעִין קֳדָם בְּנֵי יִשְׂרָאֵל עַד דִי נְעֵלִינוּן לְאַתְרֵהוֹן וְיֵתְבוּן טַפְלָנָא בְּקִרְוִין כְּרִיכִין מִן קֳדָם יַתְבֵי אַרְעָא:
@88 לָא נְתוּב לְבֵיתָנָא עַד דְיַחְסְנוּן בְּנֵי יִשְׂרָאֵל גְבַר אַחֲסַנְתֵּיהּ:
@89 אֲרֵי לָא נַחֲסִין עִמְהוֹן מֵעִבְרָא לְיַרְדְנָא וּלְהָלָא אֲרֵי קַבֵּילְנָא אַחֲסַנְתָּנָא לָנָא מֵעִבְרָא לְיַרְדְנָא מַדִינְחָא:
@90 וַאֲמַר לְהוֹן משֶׁה אִם תַּעְבְדוּן יָת פִּתְגָמָא הָדֵין אִם תִּזְדָרְזוּן קֳדָם עַמָא דַיְיָ לִקְרָבָא:
@91 וְיַעְבֵר לְכוֹן כָּל דִמְזָרֵז יָת יַרְדְנָא קֳדָם עַמָא דַיְיָ עַד דִיתָרַךְ יָת בַּעֲלֵי דְבָבוֹהִי מִן קֳדָמוֹהִי:
@92 וְתִתְכְּבֵשׁ אַרְעָא קֳדָם עַמָא דַיְיָ וּבָתַר כֵּן תְּתוּבוּן וּתְהוֹן זַכָּאִין מִן קֳדָם יְיָ וּמִיִשְׂרָאֵל וּתְהֵי אַרְעָא הָדָא לְכוֹן לְאַחֲסָנָא קֳדָם יְיָ:
@93 וְאִם לָא תַעְבְדוּן כֵּן הָא חַבְתּוּן קֳדָם יְיָ וְתֵדְעוּן חוֹבַתְכוֹן דְתַשְׁכַּח יָתְכוֹן:
@94 בְּנוּ לְכוֹן קִרְוִין לְטַפְלְכוֹן וְחַטְרִין לְעַנְכוֹן וּדְיִפּוֹק מִפּוּמְכוֹן תַּעְבְּדוּן:
@95 וַאֲמָרוּ בְנֵי גָד וּבְנֵי רְאוּבֵן לְמשֶׁה לְמֵימָר עַבְדָיךְ יַעְבְדוּן כְּמָא דִי רִבּוֹנִי מְפַקֵד:
@96 טַפְלָנָא נְשָׁנָא גֵיתָנָא וְכָל בְּעִירָנָא יְהוֹן תַּמָן בְּקִרְוֵי גִלְעָד:
@97 וְעַבְדָיךְ יַעְבְּרוּן כָּל מְזָרַז חֵילָא קֳדָם עַמָא דַיְיָ לִקְרָבָא כְּמָא דִי רִבּוֹנִי מְמַלֵל:
@98 וּפַקֵד לְהוֹן משֶׁה יָת אֶלְעָזָר כַּהֲנָא וְיָת יְהוֹשֻׁעַ בַּר נוּן וְיָת רֵישֵׁי אֲבָהַת שִׁבְטַיָא לִבְנֵי יִשְׂרָאֵל:
@99 וַאֲמַר משֶׁה לְהוֹן אִם יַעְבְּרוּן בְּנֵי גָד וּבְנֵי רְאוּבֵן עִמְכוֹן יָת יַרְדְנָא כָּל דִמְזָרַז לִקְרָבָא קֳדָם עַמָא דַיְיָ וְתִתְכְּבֵשׁ אַרְעָא קֳדָמֵיכוֹן וְתִתְּנוּן לְהוֹן יָת אַרְעָא דְגִלְעָד לְאַחֲסָנָא:
@100 וְאִם לָא יַעְבְרוּן מְזָרְזִין עִמְכוֹן וְיַחְסְנוּן בֵּינֵיכוֹן בְּאַרְעָא דִכְנָעַן:
@101 וְאָתִיבוּ בְנֵי גָד וּבְנֵי רְאוּבֵן לְמֵימָר יָת דִי מַלִיל יְיָ לְעַבְדָךְ כֵּן נַעְבֵּד:
@102 נַחְנָא נַעֲבֵר מְזָרְזִין קֳדָם עַמָא דַיְיָ לְאַרְעָא דִכְנָעַן וְעִמָנָא אֲחוּדַת אַחֲסַנְתָּנָא מֵעִבְרָא לְיַרְדְנָא:
@103 וִיהַב לְהוֹן משֶׁה לִבְנֵי גָד וְלִבְנֵי רְאוּבֵן וּלְפַלְגוּת שִׁבְטָא דִמְנַשֶׁה בַּר יוֹסֵף יָת מַלְכְּוַת סִיחוֹן מַלְכָּא דֶאֱמוֹרָאָה וְיָת מַלְכְּוַת עוֹג מַלְכָּא דְמַתְנָן אַרְעָא לְקִרְוָהָא בִּתְחוּמִין קִרְוֵי אַרְעָא סְחוֹר סְחוֹר:
@104 וּבְנוֹ בְנֵי גָד יָת דִיבוֹן וְיָת עֲטָּרוֹת וְיָת עֲרֹעֵר:
@105 וְיָת עַטְרוֹת שׁוֹפָן וְיָת יַעְזֵר וְרָמָתָא:
@106 וְיָת בֵּית נִמְרָה וְיָת בֵּית הָרָן קִרְוִין כְּרִיכָן וְחַטְרִין דְעָאן:
@107 וּבְנֵי רְאוּבֵן בְּנוֹ יָת חֶשְׁבּוֹן וְיָת אֶלְעָלֵא וְיָת קִרְיָתָיִם:
@108 וְיָת נְבוֹ וְיָת בַּעַל מְעוֹן מַקְפָן שְׁמָהָן וְיָת שִׂבְמָה וּקְרוֹ בִשְׁמָהָן יָת שְׁמָהַת קִרְוַיָא דִי בְנוֹ:
@109 וַאֲזָלוּ בְּנֵי מָכִיר בַּר מְנַשֶׁה לְגִלְעָד וְכִבְשׁוּהָ וְתָרִיךְ יָת אֱמוֹרָאָה דִי בָּהּ:
@110 וִיהַב משֶׁה יָת גִלְעָד לְמָכִיר בַּר מְנַשֶׁה וִיתֵב בַּהּ:
@111 וְיָאִיר בַּר מְנַשֶׁה אֲזַל וּכְבַשׁ יָת כַּפְרָנֵיהוֹן וּקְרָא יַתְהֶן כַּפְרָנֵי יָאִיר:
@112 וְנֹבַח אֲזַל וּכְבַשׁ יָת קְנַת וְיָת כַּפְרָנָהָא וּקְרָא לָה נֹבַח בִּשְׁמֵהּ: פפפ:

@1 **ראשי המטות.** חלק כבוד לנשיאים ללמדם תחלה ואחר כך לכל בני ישראל. ומנין שאף שאר הדברות כן, תלמוד לומר (שמות לד, לא. לב) וישבו אליו אהרן וכל הנשאים בעדה וידבר משה אליהם ואחרי כן נגשו כל בני ישראל. ומה ראה לאמרה כאן, למד שהפרת נדרים ביחיד ממחה ואם אין יחיד ממחה מפר בשלשה הדיוטות. או יכול שלא אמר משה פרשה זו אלא לנשיאים בלבד, נאמר כאן זה הדבר, ונאמר בשחוטי חוץ (ויקרא יז, ב) זה הדבר, מה להלן נאמרה לאהרן ולבניו ולכל בני ישראל, שנאמר דבר אל אהרן וגו' , אף זו נאמרה לכלן: **זה הדבר.** משה נתנבא (שמות יא, ד) בכה אמר ה' כחצות הלילה, והנביאים נתנבאו בכה אמר ה', מוסף עליהם משה שנתנבא בלשון זה הדבר. דבר אחר זה הדבר מעוט הוא, לומר שהחכם בלשון התרה ובעל בלשון הפרה, כלשון הכתוב כאן, ואם חלפו אין מתר ואין מופר:
@2 **נדר.** האומר הרי עלי קנם שלא אוכל או שלא אעשה דבר פלוני, יכול אפלו נשבע שיאכל נבלות אני קורא עליו ככל היוצא מפיו יעשה, תלמוד לומר לאסר אסר את המתר ולא להתיר את האסור: **לא יחל דברו.** כמו לא יחלל דברו, לא יעשה דבריו חלין:
@3 **בבית אביה.** ברשות אביה ואפלו אינה בביתו: **בנעריה.** ולא קטנה ולא בוגרת, שהקטנה אין נדרה נדר והבוגרת אינה ברשותו של אביה להפר נדריה. ואי זו היא קטנה, אמרו רבותינו בת אחת עשרה שנה ויום אחד נדריה נבדקין. אם ידעה לשם מי נדרה ולשם מי הקדישה נדרה נדר. בת שתים עשרה שנה ויום אחד אינה צריכה להבדק:
@5 **ואם הניא אביה אתה.** אם מנע אותה מן הנדר, כלומר שהפר לה. הנאה זו איני יודע מה היא, כשהוא אומר ואם ביום שמע אישה יניא אותה והפר, הוי אומר הנאה זו הפרה. ופשוטו לשון מניעה והסרה וכן (במדבר לב, ז) ולמה תניאון, וכן (תהלים קמא, ה) שמן ראש אל יני ראשי, וכן (במדבר יד, לד) וידעתם את תנואתי, את אשר סרתם מעלי: **וה' יסלח לה.** במה הכתוב מדבר באשה שנדרה בנזיר ושמע בעלה והפר לה והיא לא ידעה ועוברת על נדרה ושותה יין ומטמאה למתים, זו היא שצריכה סליחה, ואף על פי שהוא מופר. ואם המופרים צריכים סליחה, קל וחמר לשאינן מופרים:
@6 **ואם היו תהיה לאיש.** זו ארוסה או אינו אלא נשואה, כשהוא אומר ואם בית אישה נדרה, הרי נשואה אמור וכאן בארוסה, ובא לחלק בה, שאביה ובעלה מפירין נדרה. הפר האב ולא הפר הבעל או הפר הבעל ולא הפר האב, הרי זה אינו מופר, ואין צריך לומר אם קים אחד מהם: **ונדריה עליה.** שנדרה בבית אביה ולא שמע בהן אביה ולא הופרו ולא הוקמו:
@7 **ושמע אישה** וגו' **.** הרי לך שאם קים הבעל שהוא קים:
@8 **והפר את נדרה אשר עליה.** יכול אפלו לא הפר האב, תלמוד למר בנעריה בית אביה, כל שבנעוריה ברשות אביה היא:
@9 **כל אשר אסרה על נפשה יקום עליה.** לפי שאינה לא ברשות אב ולא ברשות בעל, ובאלמנה מן הנשואין הכתוב מדבר, אבל אלמנה מן האירוסין, מת הבעל נתרוקנה וחזרה לרשות האב:
@10 **ואם בית אישה נדרה.** בנשואה הכתוב מדבר:
@13 **כל נדר וכל שבעת אסר** וגו' **.** לפי שאמר שהבעל מפר, יכול כל נדרים במשמע, תלמוד לומר לענות נפש, אינו מפר אלא נדרי ענוי נפש בלבד. והם מפורשים במסכת נדרים (דף עט, א) :
@14 **מיום אל יום.** שלא תאמר מעת לעת, לכך נאמר מיום אל יום, ללמדך שאין מפר אלא עד שתחשך:
@15 **אחרי שמעו.** אחרי ששמע וקים, שאמר אפשי בו, וחזר והפר לה אפלו בו ביום: **ונשא את עונה.** הוא נכנס תחתיה. למדנו מכאן שהגורם תקלה לחברו הוא נכנס תחתיו לכל ענשין:
@18 **מאת המדינים.** ולא מאת המואבים, שהמואבים נכנסו לדבר מחמת יראה שהיו יראים מהם, שיהיו שוללים אותם, שלא נאמר אלא (דברים ב, ט) אל תתגר בם מלחמה. אבל מדינים נתעברו על ריב לא להם. דבר אחר מפני שתי פרידות טובות שיש לי להוציא מהם, רות המואביה ונעמה העמונית:
@19 **וידבר משה** וגו' **.** אף על פי ששמע שמיתתו תלויה בדבר עשה בשמחה ולא אחר: **החלצו.** כתרגומו לשון חלוצי צבא מזינים: **אנשים.** צדיקים, וכן (שמות יז, ט) בחר לנו אנשים, וכן (דברים א, טו) אנשים חכמים וידעים: **נקמת ה'.** שהעומד כנגד ישראל, כאלו עומד כנגד הקדוש ברוך הוא:
@20 **לכל מטות ישראל.** לרבות שבט לוי:
@21 **וימסרו.** להודיעך שבחן של רועי ישראל כמה הם חביבים על ישראל, עד שלא שמעו במיתתו מה הוא אומר (שמות יז, ד) עוד מעט וסקלני, ומששמעו שמיתת משה תלויה בנקמת מדין, לא רצו ללכת עד שנמסרו על כרחן:
@22 **אתם ואת פנחס.** מגיד שהיה פנחס שקול כנגד כלם. ומפני מה הלך פנחס ולא הלך אלעזר. אמר הקדוש ברוך הוא מי שהתחיל במצוה, שהרג כזבי בת צור, יגמור. דבר אחר שהלך לנקום נקמת יוסף אבי אמו, שנאמר (בראשית לז, לו) והמדנים מכרו אתו. ומנין שהיתה אמו של פנחס משל יוסף, שנאמר (שמות ו, כה) מבנות פוטיאל, מזרע יתרו שפטם עגלים לעבודה זרה ומזרע יוסף שפטפט ביצרו. דבר אחר שהיה משוח מלחמה: **וכלי הקדש.** זה הארון והציץ. שהיה בלעם עמהם ומפריח מלכי מדין בכשפים, והוא עצמו פורח עמהם. הראה להם את הציץ, שהשם חקוק בו, והם נופלים, לכך נאמר על חלליהם במלכי מדין, שנופלים על החללים מן האויר, וכן בבלעם כתיב (יהושע יג, כב) אל חלליהם: **בידו.** ברשותו וכן (במדבר כא, כז) ויקח את כל ארצו מידו:
@24 **חמשת מלכי מדין.** וכי איני רואה שחמשה מנה הכתוב, למה הזקק לומר חמשת, אלא ללמדך ששוו כלם בעצה והשוו כלם בפרענות. בלעם הלך שם לטול שכר עשרים וארבעה אלף שהפיל מישראל בעצתו, ויצא ממדין לקראת ישראל ומשיאן עצה רעה. אמר להם אם כשהייתם ששים רבוא לא יכלתם להם, ועכשיו בשנים עשר אלף אתם באים להלחם. נתנו לו שכרו משלם ולא קפחוהו: **בחרב.** הוא בא על ישראל, והחליף אמנותו באמנותם, שאין נושעים אלא בפיהם על ידי תפלה ובקשה. ובא הוא ותפש אמנותם לקללם בפיו, אף הם באו עליו והחליפו אמנותם באמנות האמות, שבאין בחרב, שנאמר (בראשית כז, מ) ועל חרבך תחיה:
@26 **טירתם.** מקום פלטרין שלהם, שהוא לשון מושב כומרים יודעי חקיהם. דבר אחר לשון מושב שריהם, כמו שמתרגם סרני פלשתים טורני פלשתאי:
@27 **ויקחו את כל השלל** וגו' **.** מגיד שהיו כשרים וצדיקים ולא נחשדו על הגזל לשלוח יד בבזה שלא ברשות, שנאמר את כל השלל וגו' , ועליהם מפורש בקבלה שניך כעדר הרחלים וגו' , אף אנשי המלחמה שביך כלם צדיקים: **שלל.** הן מטלטלין של מלבוש ותכשיטין: **בז.** הוא בזת מטלטלין שאינם תכשיטין: **מלקוח.** אדם ובהמה. ובמקום שכתוב שבי אצל מלקוח, שבי באדם ומלקוח בבהמה:
@29 **ויצאו משה ואלעזר הכהן.** לפי שראו את נערי ישראל יוצאים לחטף מן הבזה:
@30 **ויקצף משה על פקודי החיל.** ממנים על החיל, ללמדך שכל סרחון הדור תלוי בגדולים שיש כח בידם למחות:
@32 **הן הנה.** מגיד שהיו מכירין אותן. זו היא שנכשל פלוני בה: **בדבר בלעם.** אמר להם אפלו אתם מכניסים כל המונות [האמות] שבעולם אין אתם יכולים להם, שמא מרבים אתם מן המצרים שהיו שש מאות רכב בחור. בואו ואשיאכם עצה. אלהיהם של אלו שונא זמה הוא וכו' , כדאיתא בחלק (סנהדרין קו.) ובספרי:
@33 **וכל אשה ידעת איש.** ראויה להבעל אף על פי שלא נבעלה. ולפני הציץ העבירום והראויה להבעל פניה מוריקות: **הרגו.** למה חזר ואמר, להפסיק הענין, דברי ר' ישמעאל, שאם אני קורא הרגו כל זכר בטף וכל אשה ידעת איש וכל הטף בנשים וגו' איני יודע אם להרוג עם הזכרים או להחיות עם הטף, לכך נאמר הרגו:
@35 **מחוץ למחנה.** שלא יכנסו לעזרה: **כל הרג נפש.** ר' מאיר אומר בהורג בדבר המקבל טמאה הכתוב מדבר, ולמדך הכתוב שהכלי מטמא אדם בחבורי המת, כאלו נוגע במת עצמו, או יכול אפלו זרק בו חץ והרגו, תלמוד לומר וכל נגע בחלל, מקיש הורג לנוגע, מה נוגע על ידי חבורו, אף הורג על ידי חבורו: **תתחטאו.** במי נדה, כדין שאר טמאי מתים, שאף לדברי האומרים קברי גוים אינן מטמאין באהל, שנאמר (יחזקאל לד, לא) ואתן צאני צאן מרעיתי אדם אתם, אתם קרויין אדם ואין הגוים קרויין אדם, מודה הוא שהגוים מטמאין במגע ובמשא, שלא נאמר אדם אלא אצל טמאת אהלים, שנאמר אדם כי ימות באהל: (במדבר יט, יד) **אתם ושביכם.** לא שהנכרים מקבלין טמאה וצריכין הזאה, אלא מה אתם בני ברית, אף שביכם כשיבואו לברית ויטמאו, צריכין הזאה:
@36 **וכל מעשה עזים.** להביא כלי הקרנים והטלפים והעצמות:
@37 **ויאמר אלעזר הכהן** וגו' **.** לפי שבא משה לכלל כעס בא לכלל טעות, שנתעלמו ממנו הלכות גיעולי נכרים. וכן אתה מוצא בשמיני למלואים, שנאמר (ויקרא י, טז) ויקצף על אלעזר ועל איתמר, בא לכלל כעס, בא לכלל טעות, וכן (במדבר כ, י. יא) בשמעו נא המרים ויך את הסלע, על ידי הכעס טעה: **אשר צוה ה'** וגו' **.** תלה ההוראה ברבו:
@38 **אך את הזהב** וגו' **.** אף על פי שלא הזהיר לכם משה אלא על הלכות טמאה, עוד יש להזהיר לכם על הלכות געול. ואך לשון מעוט, כלומר ממועטין אתם מלהשתמש בכלים אפלו לאחר טהרתן מטמאת המת, עד שיטהרו מבליעת אסור נבלות. ורבותינו אמרו אך את הזהב לומר שצריך להעביר חלודה שלו קודם שיגעילנו, וזהו לשון אך, שלא יהא שם חלודה, אך המתכת יהיה כמות שהוא:
@39 **כל דבר אשר יבא באש.** לבשל בו כלום: **תעבירו באש.** כדרך תשמישו הגעלתו, מה שתשמישו על ידי חמין, יגעילנו בחמין, ומה שתשמישו על ידי צלי, כגון השפוד והאסכלה, ילבננו באור: **אך במי נדה יתחטא.** לפי פשוטו חטוי זה לטהרו מטמאת מת. אמר להם צריכין הכלים געול לטהרם מן האסור, וחטוי לטהרן מן הטמאה. ורבותינו דרשו מכאן, שאף להכשירן מן האסור הטעין טבילה לכלי מתכות. ומי נדה הכתובין כאן דרשו מים הראוים לטבול בהם נדה. וכמה הם, ארבעים סאה: **וכל אשר לא יבא באש.** כל דבר שאין תשמישו על ידי האור, כגון כוסות וצלוחיות שתשמישן בצונן ולא בלעו אסור: **תעבירו במים.** מטבילן ודיו ודוקא כלי מתכות:
@40 **אל המחנה.** למחנה שכינה, שאין טמא מת טעון שלוח ממחנה לויה וממחנה ישראל:
@42 **שא את ראש.** קח את החשבון:
@43 **וחצית את המלקוח בין תפשי המלחמה** וגו' **.** חציו לאלו וחציו לאלו:
@48 **ויהי המלקוח יתר הבז.** לפי שלא נצטוו להרים מכס מן המטלטלין אלא מן המלקוח, כתב את הלשון הזה, ויהי המלקוח שבא לכלל חלקה ולכלל מכס, שהיה עודף על בז המטלטלין אשר בזזו עם הצבא איש לו, ולא בא לכלל חלקה מספר הצאן וגו' :
@58 **וממחצית בני ישראל אשר חצה משה.** לעדה והוציאה להם מן האנשים הצובאים:
@59 **ותהי מחצת העדה.** כך וכך:
@64 **ויקח משה** וגו' **הפקדים.** הממנים:
@65 **ולא נפקד.** ולא נחסר ותרגומו ולא שגא, אף הוא בלשון ארמי חסרון, כמו אנכי אחטנה, (בראשית לא, לט) תרגומו דהות שגיא ממנינא, וכן כי יפקד מושבך (שמואל א' כ, יח) , יחסר מקום מושבך, איש הרגיל לישב שם. וכן (שם כ, כז) ויפקד מקום דוד, נחסר מקומו ואין איש יושב שם:
@66 **אצעדה.** אלו צמידים של רגל: **וצמיד.** של יד: **עגיל.** נזמי אזן: **וכומז.** דפוס של בית הרחם לכפר על הרהור הלב של בנות מדין:
@73 **עטרות ודיבון** וגו' **.** מארץ סיחון ועוג היו:
@76 **האחיכם.** לשון תמיהה הוא:
@77 **ולמה תניאון.** תסירו ותמניעו לבם מעבור שיהיו סבורים שאתם יראים לעבור מפני המלחמה וחוזק הערים והעם:
@78 **מקדש ברנע.** כך שמה, ושני קדש היו:
@82 **הקנזי.** חורגו של קנז היה, וילדה לו אמו של כלב את עתניאל:
@83 **וינעם.** ויטלטלם. מן נע ונד:
@84 **לספות.** כמו (ישעיה כט, א) ספו שנה על שנה, (ירמיה ז, כא) עולותיכם ספו וגו' , לשון תוספת:
@86 **נבנה למקננו פה.** חסים היו על ממונם יותר מבניהם ובנותיהם, שהקדימו מקניהם לטפם. אמר להם משה לא כן עשו, העיקר עיקר והטפל טפל, בנו לכם תחלה ערים לטפכם ואחר כך גדרות לצאנכם:
@87 **ואנחנו נחלץ חשים.** נזדרז מהירים, כמו (ישעיה ח, א) מהר שלל חש בז, (ישעיה ה, יט) ימהר יחישה: **לפני בני ישראל.** בראשי גיסות, מתוך שגבורים היו, שכן נאמר בגד (דברים לג, כ) וטרף זרוע אף קדקד, ואף משה חזר ופרש להם באלה הדברים (דברים ג, יח) ואצו אתכם בעת ההיא וגו' חלוצים תעברו לפני אחיכם בני ישראל כל בני חיל. וביריחו כתיב (יהושע ו, יג) והחלוץ הולך לפניהם, זה ראובן וגד שקימו תנאם: **וישב טפנו.** בעודנו אצל אחינו: **בערי המבצר.** שנבנה עכשיו:
@89 **מעבר לירדן** וגו' **.** בעבר המערבי: **כי באה נחלתנו.** כבר קבלנוה בעבר המזרחי:
@94 **לצנאכם.** תיבה זו מגזרת (תהלים ח, ח) צנה ואלפים כלם, שאין בו אל''ף מפסיק בין נו''ן לצד''י, ואל''ף שבא כאן אחר הנו''ן במקום ה''א של צנה הוא. מיסודו של ר' משה הדרשן למדתי כן: **והיצא מפיכם תעשו.** לגבוה שקבלתם עליכם לעבור למלחמה עד כבוש וחלוק. שמשה לא בקש מהם אלא ונכבשה ואחר תשבו, והם קבלו עליהם עד התנחל, הרי הוסיפו להתעכב שבע שחלקו, וכן עשו:
@95 **ויאמר בני גד.** כלם כאיש אחד:
@98 **ויצו להם.** כמו עליהם, ועל תנאם מנה אלעזר ויהושע, כמו (שמות יד, יד) ה' ילחם לכם:
@102 **ואתנו אחזת נחלתנו.** כלומר בידינו וברשותנו תהי אחזת נחלתנו מעבר הזה:
@106 **ערי מבצר וגדרות צאן.** זה סוף הפסוק מוסב על תחלת הענין, ויבנו בני גד את הערים הללו להיות ערי מבצר וגדרות צאן:
@108 **ואת נבו ואת בעל מעון מוסבת שם.** נבו ובעל מעון שמות עבודה זרה הם, והיו האמוריים קורים עריהם על שם עבודה זרה שלהם, ובני ראובן הסבו את שמם לשמות אחרים, וזהו מסבות שם, נבו ובעל מעון מוסבות לשם אחר: **ואת שבמה.** בנו שבמה והיא שבם האמורה למעלה:
@109 **ויורש.** כתרגומו ותריך. שתבת רי''ש משמשת שתי חלקות לשון ירשה ולשון הורשה, שהוא טירוד ותירוך:
@111 **חותיהם.** כפרניהון: **ויקרא אתהן חות יאיר.** לפי שלא היו לו בנים קראם בשמו לזכרון:
@112 **ויקרא לה נבח.** לה אינו מפיק ה''א. וראיתי ביסודו של רבי משה הדרשן לפי שלא נתקים לה שם זה, לפיכך הוא רפה, שמשמע מדרשו כמו לא. ותמהני מה ידרוש בשתי תיבות הדומות לה (רות ב, יד) ויאמר לה בעז, (זכריה ה, יא) לבנות לה בית:

@1 **אל ראשי המטות וגו'**. צריך לדעת מה נשתנית מצוה זו שפרט בה הכתוב **ראשי המטות**, ורז''ל בספרי אמרו לפי שבמאמר החצוצרות הקדים קריאת העדה לנשיאים חש לומר שהעדה קודמת לנשיאים תלמוד לומר אל ראשי וגו' שהם הקודמים, ובמקום אחר (נדרים עח: ב''ב קכ:) אמרו שבא לומר היתר נדרים ביחיד מומחה, וכל זה דרך דרש ואסמכתות עוד צריך לדעת למה הוצרך לומר **המטות לבני** שלא היה לו לומר אלא אל ראשי מטות בני ישראל, והיה נראה לומר שנתכוון לדבר בסדר זה שלא תאמר שלא באה המצוה אלא לראשי המטות ישראל לבד לזה אמר אל ראשי המטות לבני ישראל, וכאילו אמר לזה ולזה, והגם שלא אמר ולבני, הרבה מקראות מדברים בסדר זה כדרך אומרו (שמות א) ראובן שמעון וגו' וכאילו אמר ושמעון:
@1 **אלא** שראיתי ברייתא (שם) וזה לשונם תניא יכול שלא אמר משה פרשה זו אלא לנשיאים בלבד נאמר כאן זה הדבר ונאמר בשחוטי חוץ (ויקרא יז) זה הדבר מה להלן וכו' אף זו נאמרה לכלן, אם כן אין משמעות אומרו לבני ישראל ולבני ישראל שהרי הוצרכו בברייתא להוכיח מגזירה שוה וכבר אמרו רז''ל (כריתות ה.) וזה לשונם לעולם אל תהי גזירה שוה קלה בעיניך וכו', עוד צריך לדעת כוונת אומרו **לאמר** כי למי יאמרו בני ישראל, ואם הכוונה היא שראשי המטות יאמרו לבני ישראל, היה לו לומר לאמר לבני ישראל. עוד אומרו **זה** הדבר מה בא למעט בתיבת זה:
@1 **אכן** יתבאר הכתוב בהקדים מאמרם ז''ל שאמרו (חגיגה י.) וזה לשונם היתר נדרים פורחים באויר עד כאן, ויש להעיר למה עשה ה' ממצוה זו סדר זה מה שלא עשה כן בכל התורה שכל דבר ודבר כתוב יושר וזו פורחת באויר:
@1 **אכן** הטעם הוא כי לא רצה ה' שיהיה כתוב לעין כל אדם שהנדר והשבועה ישנה בהיתר שבזה יזלזלו בנדרים ובשבועות, ולזה נתחכם ה' והעלים הדבר ומסר ההתר לגדולי ישראל שהם ידעו ויבחינו חילוקי המשפטים שבהתר, אבל בפני כל ההמון יהיו נעולי דלת לקיים כל נדר וכל שבועה כאומרו לא יחל וגומר ככל היוצא מפיו וגו'. וזה הוא שיעור הכתוב **וידבר משה אל ראשי המטות** שהם גדולי ישראל המצוה בשלימות, אבל **לבני ישראל לאמר זה הדבר** פירוש כי לבני ישראל בכללות לא יאמר להם מהדיבור הנאמר לראשי המטות אלא זה הדבר ולא הפורח באויר שנאמר בעל פה לראשי המטות, ובזה נתיישבו כל הדקדוקים:
@1 **או** ירצה על זה הדרך אל ראשי המטות באה המצוה, **ולבני ישראל לאמר** פירוש כי הנודר והנשבע מבני ישראל יבא ויאמר לראשי המטות והם יגידו למו את שישנו בבל יחל ואת שישנו בהתרה כפי ההלכות שבאו במשפט זה:
@1 **ואם** תאמר לכל הדרכים הרי הוזכרו גם בני ישראל במצוה זו ולמה הוצרכו רז''ל ללמוד הדבר כנזכר, יש לומר שלא הוצרכו לדון בגזירה שוה, אלא לומר שמשה אמר הדברים מפיו לישראל, אבל להודעת המצוה לישראל לא הוצרכו לגזירה שוה, וזה הוא מה שדקדקו לומר יכול שלא אמר משה פרשה זו אלא לראשי המטות ולא אמרו יכול שלא נאמרה פרשה זו אלא לראשי המטות שאז תהיה הכוונה שלא נאמרה כל עיקר:
@1 **עוד** יש לומר שזולת גזירה שוה שהודיעה שמצוה זו נוהגת בישראל הייתי יכול לפרש אומרו לבני ישראל כאלו אמר של בני ישראל ויהיה הדבר שקול, ואחר שבאה גזירה שוה שהצדיקה המצוה גם בישראל אנו מישבים הכתוב כדרך האמור, ואין להקשות לפי מה שפירשנו זה הדבר שבא למעט שלא יאמר לכל שהנדרים ניתרים בפה והרי צריכה זה הדבר לגזירה שוה, כי הגזירה שוה גמר לה מתיבת הדבר ופירושינו הוא מתיבת זה לבד הגם שהיה אומר זה אשר צוה ה':
@1 **ובדרך** רמז יתבאר אומרו לבני ישראל **לאמר זה הדבר** על פי מה שאמרו רז''ל (מ''ר כאן) וזה לשונם לעולם יהיה אדם זהיר בנדרים אלף עיירות היו לו לינאי וכו', הרי שהגם שהיו מקיימין שבועתן נענשו, ואמר הכתוב כאן כי יש נדרים ושבועות שצוה ה' אותם, והוא אומרו **לבני ישראל לאמר** אין לאמר אלא גילוי עריות (סנהדרין נו:) פירוש לחשש העריות זה הדבר אשר צוה ה' איש כי ידור נדר וגו', ודקדק לומר **איש** לרמוז לתגבורת ניגוד התאוה כאומרם ז''ל (רות רבה פ''ו) בפסוק חי ה' שכבי וגו' שנשבע ליצרו, וכן אמרו (חגיגה י.) בפסוק נשבעתי ואקיימה לשמור וגו' כי מצוה לישבע ליצרו:
@2 **איש כי ידור נדר לה' וגו'**. צריך לדעת למה כפל לומר **ידור נדר או השבע שבועה** ולא הספיק לומר כי ידור לה' או ישבע. עוד למה כפל לומר **לא יחל** וגו' **ככל היוצא מפיו**. אכן לפי שיש ב' מיני נדרים ושבועות, אחד בעניינים הנוגעים לנפש ויתחלק לב' עניינים אחד לעשות מעשה הטוב כגון ללמוד וללמד להקדיש לגמילות חסדים ואחד להרחיק התיעוב להגדיר עצמו לבל ידור בשכונת אשה חשודה לבל ילך בחברת פועלי און וכדומה, ב' בענינים הנוגעים לגוף במעשה שאין בו לא איסור ולא מצוה, וגם זה יתחלק לשני דברים, לאכול ולשתות לדור בדירה זו וכדומה, או שלא לאכול דבר פלוני ושלא ללבוש מלבוש זה וכדומה, ויצו ה' משפטיו כדת מה לעשות, ואמר כי ידור נדר סתם נדר יגיד על המעשה שנדר ללכת למקום פלוני או לעשות איזה דבר, ולפי שיש נדר שהוא לה' ודינו משונה מנדרי חול כאשר יבאר הכתוב לזה פרטו ואמר נדר לה', נמצאת אומר שהזכיר הכתוב ב' מיני נדרים נדרי חול ונדרי קודש:
@2 **ואומרו** או **השבע שבועה** כנגד העדר המעשה כמו שגמר אומר לאסור איסר על נפשו, ויש גם כן בזה ב' נדרים, נדרי חול כגון לאסור דברים שאין מצוה באיסורם, או לאסור גם כן דברים שהם אסורין כגון בועז שנשבע ליצרו, ונתחכם ה' במה שאמר תיבת **לה'** בין נדר לשבועה להסמיך לה' נדר ושבועה לומר שהכפל שבא בנדר ובשבועה הוא פרט הנוגע לה' ולא כללו בכלל נדרי חול לפי שדינו משונה, והוא מה שגמר אומר **לא יחל דברו ככל היוצא** וגו' פירוש כנגד נדרים שהם דברי חול ושבועות שהם מניעת דברים שאין בהם צורכי מצוה כשבועתו של בועז וכדומה לה אמר לא יחל פירוש הוא לא יחל אבל אחרים מתירים לו וכמו שפירשו רז''ל (שם), וכנגד נדרים שהם נדרי הקדשות ונדרי שמים ושבועות שיש בהם צורכי מצוה אמר ככל **היוצא מפיו יעשה** בזה אין בהם תנאי שאחרים יכולין להתירו אלא הם דברים שאין להם התרה:
@2 **עוד** נראה לפרש טעם אומרו **לה'** על פי מה שכתב רמב''ם בפרק י''א מהלכות נדרים וזה לשונו קטן בן י''ב שנה שנשבע או שנדר בודקים אותו אם יודע לשם מי נדר וכו' עד כאן, והוא מה שנתכוין ה' במאמר **נדר לה'**, כי לפי שקדם ואמר **איש** בא לתת גדר שיקרא איש לדבר זה ואמר נדר לה' פירוש כשידע לשם מי נדר וכן בשבועה כאומרו או השבע שבועה שהדין כמו כן בשבועה:
@4 **ושמע אביה את נדרה וגו' וקמו כל נדריה וגו'**. צריך לדעת למה התחיל לדבר לשון יחיד, כאומרו נדרה וגמר אומר לשון רבים כאומרו נדריה, גם מה מרבה בתיבות כל נדריה וכל איסר שלא היה לו לומר אלא וקמו נדריה ואסריה. עוד למה שינה בנדרים אמר **וקמו נדריה** ובאסרים **יקום**, גם לא היה צריך לומר יקום והיה סומך על מאמר וקמו שאמר בתחלה, ויתבאר הכתוב על פי מה שאמרו במסכת נדרים דף פ''ז וזה לשונם המשנה אמרה קונם תאנים וענבים קיים לתאנים כולו קיים הפר לתאנים אינו מופר עד שיפר גם לענבים, אמרה קונם ענבים שאיני טועמת ותאנים שאיני טועמת הרי אלו ב' נדרים עד כאן:
@4 **ואמרו** בש''ם וזה לשונם מתניתין ר' ישמעאל הוא דתניא אישה יקימנו אמרה קונם תאנים וענבים וכו' קיים לתאנים כלו קיים וכו' הפר לענבים אינו מופר עד שיפר גם לתאנים דברי רבי ישמעאל, רבי עקיבא אומר הרי הוא אומר אישה יקימנו וגו' מה יקימנו ממנו אף יפירנו ממנו, ורבי ישמעאל, מי כתיב יפר ממנו, ורבי עקיבא, מקיש הפרה להקמה, אמר ר' יוחנן זו דברי רבי ישמעאל ורבי עקיבא אבל חכמים אומרים מקיש הקמה להפרה מה הפרה מה שהפר הפר אף הקמה מה שקיים קיים עד כאן, זו היא גירסת הספרים שלפנינו, אבל התום' ורמב''ן והר''ן גורסים אבל חכמים אומרים מה הפרה מה שהפר לא הופר אף וכו', ולפי גירסא זו חכמים ורבי ישמעאל הם בסברא אחת בענין ההפרה שלא הופר, וגירסה זו היא עיקר כמו שהוכיחו מהתוספתא:
@4 **נמצינו** אומרים ג' סברות, א' היא סברת ר' ישמעאל שהביא רבי במשנה שאם הקים חלק מהנדר הקים הכל ואם הפר חלק מהנדר אינו מופר אפילו חלק שהפר. ב' סברת רבי עקיבא שכל שהקים מקצת או הפר מקצת כאלו הקים או הפר הכל. ג' סברת חכמים שסוברים שבין בהפרה בין בהקמה אין הקמתו והפרתו כלום אלא אם הקים או הפר הכל, ולכל אחד מג' הסברות יתיישב הכתוב על נכון, לסברת ר' ישמעאל שסתם רבי במשנה כמותו יתיישב על זה הדרך אומרו ושמע אביה את נדרה לשון יחיד לומר שבנודרת נדר אחד הכתוב מדבר וכגון שאמרה קונם תאנים וענבים שזה יקרא נדר אחד לאפוקי אם אמרה קונם תאנים שאיני טועמת קונם ענבים וכו' שזה יקרא ב' נדרים:
@4 **ואומרו והחריש** וגו' **וקמו** כל נדריה פירוש אפילו לא החריש אלא מפרט אחד פירוש שמהתאנים והענבים שנדרה בהם לא החריש אלא לתאנים וקמו כל נדריה פירוש אפילו לענבים, ובזה העירך כי אומרו **והחריש** אין הכוונה מהכל שהרי הוצרך להודיעך בקיום ואמר וקמו כל הא למדת שעד עתה במאמר והחריש לא היינו עסוקים לכל נדריה, ואומרו **וכל איסר** וגו' **יקום** נתכוון בשינוי זה להזכירו בלשון יחיד לגלות שמאמר כל נדריה לא שהם נדרים רבים אלא נדר אחד הוא אלא שכללה בו דברים רבים תאנים וענבים, ובערך הנידרים הוא שאמר לשון רבים, והוא אומרו וכל איסר וגו' יקום, והגם שהמאמר בא באיסר, כבר הודיעך הכתוב שדין הנדר והשבועה שוים:
@4 **ואומרו יקום** ולא סמך על מאמר וקמו שקדם, שאם כן הייתי מפרש כוונת הכתוב שבא לומר שאם נדרה ונשבעה על ב' דברים יחד והחריש לנדר קיים גם לשבועה, לזה אמר יקום לומר שצריך הקמה לכל אחד מהם, ואומרו **ואם הניא** וגו' כל נדריה פירוש צריך שיפר כל נדריה פירוש אם לא הפר אלא לתאנים אינו מופר עד שיפר גם לענבים, ואומרו **לא יקום** לשון יחיד להעירך שבנדר אחד הכתוב מדבר, לבל תטעה ממאמר נדריה וגו' שאין הכתוב מדבר אלא בנודרת נדרים רבים כדין האמור בסיפא של המשנה שכתבנו למעלה:
@4 **ולסברת** רבי עקיבא שבהפרת חלק הופר הכל ובהקמת חלק כמו כן הוקם הכל יתבאר על זה הדרך **ושמע אביה את נדרה** וגו' **והחריש** וגו' פירוש אם שמע אפילו חלק מנדרה הגם שלא שמע כל נדרה והחריש לאותו חלק בזה ו **קמו כל נדריה** אפילו חלק שלא שמע, ואומרו **ואם הניא אביה אותה** פירוש אפילו לא הניא הכל אלא חלק אחד כל שאנו קורין בו הניא אותה, ולזה לא הסמיך מאמר כל נדריה למאמר ואם הניא על זה הדרך ואם הניא אביה כל נדריה ביום שמעו, ואז לא היה צריך לומר תיבת אותה, וכפי זה מאמר כל נדריה וגו' נמשך למטה למאמר לא יקום, ואמר **לא יקום** לשון יחיד נתכוון בזה לומר חידוש הדין שאפילו מה שלא הפר הופר:
@4 **ולדרך** זה יתישב על נכון מאמר **וה' יסלח לה** וגו', פירוש שאם לא הניא אביה אלא לענבים והיא אינה יודעת המשפט שגם לתאנים הועיל הביטול ואכלה תאנים מודיע הכתוב שה' יסלח לה כי צריכה סליחה כיון שלדעתה לא הניא על התאנים, ונתן טעם הסליחה כי הניא אביה אותה פירוש כי הביטול שעשה אביה הועיל גם לזה, והוצרך לומר כן להעירך שהדבר שעליו בא הסליחה הוא על העדר ידיעה זו שממנה יצאה השגגה והבן:
@4 **ולסברת** חכמים שאמרו שלא תועיל הפרה למקצת ולא הקמה למקצת עד שיפר לכל או יקום לכל יתבאר על זה הדרך ושמע אביה את נדרה אמר לשון יחיד להעירך שהכתוב מדבר בעשתה נדר אחד ולא בעשתה ב' נדרים כמו שפירשתי לסברת רבי ישמעאל ואומרו **והחריש** וגו' **וקמו כל נדריה** מאמר כל נדריה נמשך לפניו ולפני פניו וזה פירושו והחריש לה אביה אימתי יועיל החרישה להקים אם יהיו כל נדריה אבל חלק ממנה לא תועיל לו הקמה:
@4 **ואומרו ואם הניא** וגו' **כל נדריה** וגו' מאמר כל נדריה נמשך למעלה על זה הדרך **ואם הניא** וגו' אם בהפרתו הניא הכל אז לא יקום פרט מהם, ולהודיעך בא שאם הניא פרט אחד אין אנו קורים בו לא יקום, והגם שנאמר שמאמר כל נדריה נמשך למטה למאמר לא יקום יתבאר על זה הדרך כל נדריה וגו' לא יקום פירוש בזמן שיש כל נדריה בכלל אז ישנו לפרט הא למדת שאין ביטול לפרט לבדו, וכל זה דוקא שעשתה נדר אחד כמו שרשם במאמר ושמע אביה את נדרה, אבל אם עשתה אותם בגדר ב' נדרים אין נתלה זה בזה:
@12 **ואם הפר יפר וגו'**. טעם שכפל לומר **הפר יפר**, גם ריבוי **כל מוצא**, יתבאר על פי מה שאמרו בנדרים פרק י''א (פ''ב:) וזה לשונם אמר רב יהודה וכו' נדרה מב' ככרות בא' מתענה ובאחת אין מתענה מתוך שהוא מפר למתענה מפר גם לשאינה מתענה עד כאן, והוא מה שנתכוון הכתוב בכפל **ואם הפר יפר** פירוש אם הפר בחלק שיש לו הפרה. יפר לרבות גם חלק שאין לו בו דין הפרה, ואמר **כל מוצא שפתיה** וגו' פירוש טעם שהוא מפר גם חלק שאין בו דין הפרה לפי שהוא כלול עם דבר שיש בו הפרה וכשהוא מפר מפר כלם יחד, ולסברת רב אסי שחלק שם בנדרים וזה לשונו רכ אסי אמר מפר למתענה ואינו מפר לשאינו מתענה עד כאן, יתבאר על זה הדרך אם הפר פירוש דבר שיש בו דין הפרה, יפר פירוש תועיל הפרתו אבל לא חלק שאין בו דין הפרה, ואומרו **כל** וגו' **לנדריה** פירוש אפילו הם כלולים יחד ב' דברים אחד מתענה בו ואחד אין מתענה בו:
@12 **עוד** יתבאר על פי מה שאמרו שם במשנה דף פ''ז וזה לשונם יודע אני שיש מפירין אבל איני יודע שזה נדר רבי מאיר אומר לא יפר וחכמים אומרים יפר עד כאן, והוא מה שנתכוון הכתוב במאמר **הפר יפר** פירוש אפילו אין לו שגגה אלא בהפרה תועיל לו להפר אחר זמן כשידע שיש מפירין זו כדברי חכמים, ולרבי מאיר יתבאר הכפל לומר שיש מציאות שהגם שלא הפר בזמנו יפר שלא בזמנו וכגון שלא ידע שיש מפירין, ואומרו **לנדריה** לסברת רבי מאיר יתיישב על זה הדרך אימתי אמרתי לך שיכול להפר אחר כך כשלא היתה לו השגגה בנדרים, והוא אומרו **לנדריה** פירוש כשיכיר נדריה, ולסברת חכמים יתבאר אומרו לנדריה הכרת היותה נדריה, הא למדת שבה שגג ואף על פי כן ריבה בו הפרה לומר שיכול להפר לכשידע שהם נדרים:
@15 **ואם הפר יפר**. פירוש אפילו בנדרים שיש בהם הפרה אם יפר ונשא וגו':
@17 **וידבר ה' וגו' לאמר נקום וגו'**. קשה אם הדיבור בא לאמר לישראל כנשמע מתיבת לאמר היה לו לומר נקמו נקמתכם מאת וגו', ובמדרש תנחומא אמרו וזה לשונם אין וידבר אלא לשון עז וכו' התחיל משה לפייס הקדוש ברוך הוא על מיתתו ולא נתפייס וכו' אמר לו משה לי ראוי מיתה שראיתי נפלאות וכו' ופייסו ה' בב' דברים אם אתה רוצה לחיות שנים רבות לא יראו ישראל במפלת אויביהם ולא תכבש מדין לפניהם וכו' וכיון שנתפייס משה היה קשה לפני הקדוש ברוך הוא שקנס עליו מיתה וכו' עד כאן, הנה בעל המדרש הרגיש במה שדקדקנו ולדבריו יתיישב הכתוב על נכון, וידבר לשון קושי זה ירמוז לב' מיני קושי, א' למשה על מיתתו, וא' בעיני ה' על שקנם על ידידו המיתה, ותיבת **לאמר** נתכוון לרמוז אל הפיום שפייס ה' למשה להתפייס למות מטעם נקום וגו' כאמור במדרש, או ירצה בתיבת **לאמר** להודיע ריצוי שריצה משה לה' כדי שלא ימות, וענהו ה' נקום וגו' פירוש בשביל שינקום מאויבי ישראל:
@17 **ולפי** פשט הכתוב יתבאר על זה הדרך וידבר ה' אמר לשון דבור לומר דיבר אליו דבר מלך שלטון כשאר כל הציווים שבתורה, ואומרו **לאמר** כפשטה לאמר לישראל ככל לאמר האמורה בתורה, וכאן צריכה ליאמר יותר מכל המקומות לפי שאמר נקום תבא לו הסברא שהוא לבד יעשה הנקמה כפשט המאמר ואין זה דבר זר כי גבור חיל היה וה' בעזרו, וצא ולמד מיהונתן בן שאול וגו' (ש''א י''ד) ומכל שכן משה גבור הגבורים לז''א אליו לאמר לישראל, ואומרו **נקום** וגו' פירוש לפי שתלה לו ה' מיתתו בנקמת מדין דכתיב אחר תאסף וגו' אמר אליו כי במה שיאמר הדברים הוא להם בזה מעלה עליו הכתוב שהוא הנוקם כי הוא מוסר נפשו ממש על הדבר שהגם שיודע שבאמצעות כן ימות אף על פי כן יאמר לישראל מה שאמר בסמוך אין לך קיום מצות בכל נפשך כזו, ובסמוך יתבאר באופן אחר:
@18 **נקום נקמת וגו'**. משמעות הכתוב יגיד שהטיל ה' על משה להנקם ממדין, וראינו שאפילו למלחמה לא יצא עמהם, והגם שפירשתי שהנקמה היא האמירה שיאמר להם, על כל זה פשט הכתוב משמע שהוא עצמו ינקום לא שישלח פינחם במקומו, עוד למה תלה אסיפת משה בנקמת מדין:
@18 **אכן** כונת מאמר נקום סובלת ב' דרכים, א' הוא השתדלות סדר המעשה פירוש התחכמות סדר המלחמה לתועלת הניצחון בין בשיעור הצריך בין בסדר שבו ישיג לאבד קמיו והערכת הלוחמים וכדומה, ב' המלחמה עצמה שהיא פעולת הנקמה, והבין משה פירוש צודק כי כונת נקום וגו' שאמר ה' היא התחכמות סדר הדבר שבאמצעותו תהיה הנקמה, ופירוש זה הצדקתו היא ממה שלא אמר לו ה' בפירוש הלחם במדין שהוא לשון מוכרע, גם לפי שהשכיל במה שלפנינו שהוא צריך להתחכמות בסדר הדבר מטעם כי הנה העם אשר יצו ה' עליהם הנקמה הם עם אשר נכשלו בני ישראל בהם בעריות מהם במעשה מהם במחשבה, והגם שנגף ה' כמה וכמה סוף כל סוף ימנע מהם הנם בהם, ואדרבה יקטרג המקטרג להפילם במלחמותם לצד שמץ העון, וזה ידמה למעשה העגל שהגם שנגף ה' כל עובדיו עם כל זה יצו ה' לבל יכנס כהן גדול לפנים בבגדי זהב, גם צוה (פדר''א פ''ד) שוכני שמים לכסות בכנפיהם את רגליהם שדומים לרגל עגל לבל יתעורר המקטרג, ומכל שכן בעת המלחמה שיתעורר המקטרג על החטא שבא מהם, וצא ולמד (סוטה מד:) שיעור החטא שיחזרו עליו מעורכי המלחמה, וכמו כן יתפסו בכל שהוא מהרהור התיעוב, ואין צריך לומר שיהיו מנועי הנס, ולזה כשאמר ה' למשה נקום אמר ודאי כונת ה' הוא התחכמות בסדר הענין להרים המיחוש האמור, וזו היא עיקר הדבר שתעלה בידם הנקמה, וכמו כן עשה בחכמתו עבד ה' כאשר אבאר בסמוך:
@18 **ואומרו אחר תאסף אל עמך** נראה כי נתכוין לומר לו שקודם לכן אינו שלם התיקון יאסף אל עמיו, פירוש שיהיה לו מונע בדין וימנענו מגשת נפשו למקום מושבה שיקרא עמיו כידוע עד שיעמידנו במשפט, כי על הכל יביא ה' במשפט וסביביו נשערה מאוד, והמונע הוא לפי שהשלם הזה נתרפה במעשה זמרי ולא עשה דבר כאומרם ז''ל (במד''ר פ''כ) שרפו ידיו והקפיד ה' עליו שלא נקם עד שעמד פנחס, ולזה כשהגיע זמן פטירתו אמר ה' אליו תיקון לדבר זה שנמנע מהתנקם מעושי רשע יקום ויתנקם ממדין שסבבוהו, ואחר שישלים התיקון ליאסף אל עמיו באין שטן ואין וכו', וזה מחסדי אל ואהבתו לידידיו ינחם במעגלי צדק:
@18 **מאת המדינים**. אומרו **מאת** ולא הספיק לומר מהמדינים, אולי שרמז לזולתם הנמצא אתם והוא בלעם שנמצא שם אז והרגוהו דכתיב (ל''א ח') ואת בלעם וגו'. ואולי כי לזה מיהר ה' הדבר קודם שיחזור בלעם לארצו כי לא היה במדין אלא לקחת שכרו כאומרם ז''ל (סנהדרין קו.) ועומד לחזור, וה' פרש רשת לרגלו וצדו לחרב נוקמת:
@19 **וידבר וגו' לאמר החלצו וגו'**. צריך לדעת א' אומרו **לאמר** למי יאמרו. ב' אומרו **החלצו** וגו' למה לא צוה כסדר שאמר במלחמת עמלק ליהושע (שמות י''ז) בחר לנו אנשים כמו כן כאן היה לו לצוות לפינחס ששלח עמהם ולא לכללות העם, גם שאין דרך זה נכון כי מי מפים לדעת מי זה הוא שיזרז עצמו לצאת וכל אחד יאמר לא עלי המצוה לעשות. ג' אומרו **ויהיו על מדין** שהיה לו לומר וילחמו במדין כדרך אומרו (שם) הלחם בעמלק. ר' למה שינה מדברי ה' כי ה' אמר אליו נקום נקמת בני ישראל והוא אמר נקמת ה' והיה צריך לדייק מאמר ה'. ה' אומרו **אלף למטה** למה לא שלח כל העם לעשות נקמה בגוים הרשעים ועל מי סמך לשלוח אנשים מועטים י''ב אלף לעם רב, וצא ולמד ריבויים מטפם הנשארים שהיו שנים ושלשים אלף:
@19 **אכן** לפי מה שהקדמנו כי יש בענין מלחמה זו מיחוש צודק ולזה בא האלהים בנועם דבריו למשה נקום וגו' להעירך סדר המלחמה בסדר שבו יקיים דבר הנקמה אשר צוה ה', לזה נתחכם ולא רצה לבחור אנשים על ידי הזולת כי מי יודע האנשים אשר לא חשבו מחשבות און ולא טעו במכשול אומה זו, ויעץ ואמר להם שיחלצו מהעדה פירוש הם מעצמן כל מי שיודע עצמו שהוא בר לבב ונקי כפים ימסר לחשבון האלף למטה, והוא מה שרמז בתיבת **לאמר** מאמר הנעלם שהוא ענין נקיותם מחטא מדין להבחין בעצמו כל אחד מהנמסרים אם הוא נקי ובר, ואולי כי רמז גם כן בתיבת **לאמר** ענין העריות כאומרם ז''ל (סנהדרין נו:) לאמר זו גילוי עריות שאמר להם שצריכין שיהיו החלוצים נקיים מהחטא, וכמו שגמר אומר אנשים לצבא ואמרו רז''ל (תנחומא) כל אנשים צדיקים והגם שפירשנו במקומות אחרים שאין זה אלא כשתהיה תיבת אנשים יתירה, במה שלפנינו יגיד עליו ריעו מה שדייקנו בענין, ולזה אין להם לחוש למכשול כיון שהיוצאים לצבא צדיקים, ועוד להם שיקראו חסידים כיון שבא לידם עון זה וניצולו ממנו כאומרם ז''ל (זוח''ג קצה:) שלזה יקרא חסיד, באמצעות כן תהיה הנקמה באין מיחוש, ולזה לא רצה שירצו כל ישראל לצבא כי בדרך זה יש מיחוש מניעת הנקמה ואדרבה להיפך כנזכר:
@19 **ואומרו ויהיו על מדין** יתבאר על פי מה שאמרו אנשי אמת שבחינת הקדושה הוא יסוד העליה ובחינת הקליפה היא סוד הירידה וכשאדם חוטא ונדבק בו חלק הרע תפעיל בו טבעה ויסודה להשפילו, ופרט זה פירשנוהו בפרשת כי תשא את ראש בני ישראל שהחוטא יכוף כאגמון ראשו ועומד בגדר השפלות, והוא אומרו **ויהיו על מדין** פירוש שלא יהיה בהם מהטומאה הסובבת השואתם למדין אלא יהיו בגדר הטוב שעומדים למעלה:
@19 **ואומרו לתת נקמת ה'** גם זה מההתחכמות להשגת הנקמה שצוה אותם שתהיה כוונת הנקמה לקנאת ה' אשר גרמו ביטול מצותיו ורצונו יתברך ולא להתנקם על המסובב מהחטא שמתו כמה מישראל, כי לכשתהיה הכוונה על זה אין במעשה מצוה להסתייע באמצעותם להנקם מאויב, והגם שה' אמר אליו נקמת בני ישראל, לא אמר אליו שיאמר לישראל לשון זה אלא שדבריו היו עם משה נקום נקמת בני ישראל, ומשה נתחכם לעשות הדבר בדרך זה לקיים הנקמה של ישראל שנצטווה עליה במאמר נקום:
@19 **עוד** יתבאר הכתוב על זה הדרך שאין צורך שילחמו הם אלא יהיו שם עליהם פירוש בשבילם, והטעם **לתת נקמת ה'** פירוש נקמה שיתנקם ה' במדין באמצעותם על דרך אומרו (שמות יד) ה' ילחם לכם, ואמר הכתוב **וימסרו מאלפי ישראל** פירוש כל מי שהיה יודע בעצמו שעומד בצדקו מסר עצמו לדבר עד שבאו לכלל האלף, והגם שהיו בישראל כהנה וכהנה מהצדיקים, נתחכם ה' כדי שלא לבייש הנשארים שלא יהיו ניכרים:
@22 **וישלח וגו' אותם ואת פנחס וגו'**. אומרו **וישלח**, נתכוין לעשותן שלוחי מצוה לנקום נקמת ה' ושלוחי מצוה אינן ניזוקין, וכפל לומר אותם פעם ב' לרמוז ששקול פנחם כנגד כלן, וטעם שבחר בפנחם ולא יהושע וכדומה, גם זה מהתחכמות הנקמה כי זה הוא אשר קינא ועשה בהם שפטים מופלאים וסמוך הוא בכח מופלא להשמיד כל האומה הטמאה, גם אפשר שחש משה לקטרוג האנשים למה לא מיחו בזונים הגם שהם נקיים לזה נתחכם ושלח המקנא קנאת ה' במסירת נפשו, ואולי כי הוא מה שדקדק במאמר **אותם ואת פנחס** לומר ישלים זה מה שחסר לזה, ואולי כי דבר זה היה בלב תעלומות חכמה שנקמת מדין צריכה להיות על ידי פנחם, והן האדון חשב לטובה שלא יכלים משה לומר לו בפירוש שלח את פנחם שזה יגיד שנפסל ח''ו הוא מהמעשה, לזה נתחכם ותלה הדבר ביד משה ואמר לו נקום וגו' ומשה מעצמו ידע הנכון עשות וישלח פנחס, ובזה נעשית מחשבת ה' לטובה ולא נכלם משה ידיד ה':
@24 **ואת מלכי וגו' חמשת וגו'**. טעם שהוצרך הכתוב להזכיר מניינם, לומר שנהרגו יחד זה עם זה וראו זה את זה במפלתן. ואומרו **מלכי מדין** פעם ב' אולי שנתכוין בכפל הדברים לומר שהרגום בידיעה שהם מלכי מדין ולא בהסח הדעת:
@24 **הרגו בחרב**. הוצרך לומר **הרגו** הגם שמובן הוא שהרגוהו מסמיכות זכרונו עם הנהרגים, יתבאר על פי דבריהם ז''ל (ספרי) שאמרו כי בלעם הלך ממדין לקראת ישראל ליעצם לבל ילחמו במדין ואמר להם ומה כשהייתם כו' עד כאן, הדברים יגידו כי בלעם נהרג קודם הריגת ה' מלכי מדין, והוא מה שנתחכם ה' ויחד לו הריגה בפני עצמו להעירך שלא נהרג עמהם שלא היה מובן כן אם לא היה אומר הרגו, ואומרו **בחרב** לומר שבטלו כשפיו בערך ישראל והרגוהו בגשמי:
@32 **הן הנה וגו' בדבר בלעם**. צריך לדעת כונת אומרו **הן הנה**, עוד למה האריך לומר בדבר בלעם וגו' על דבר פעור, ויתבאר הדבר בהעיר למה שגגו פינחם וצדיקי עליון שהלכו עמו בדבר זה:
@32 **אכן** פינחס ואנשי הצבא דנו ופטרום מטעם שהנשים כפופות הן לבעליהם ולאבותיהם ואנוסים המה, והן האדון משה רבינו עליו השלום הרגיש שמטעם זה החיו אותם ובא בטענה הנשמעת ואמר בשלמא אם לא היו עושים אלא מעשה הזנות שבא להם עליו מצות גדוליהם יש לדון אותם לזכות, אלא שהם עשו מעצמן מעשה אחר מה שלא ציוו אותם גדוליהם שהוא מעשה פעור שאמרו רז''ל (במד''ר פ''כ) שהיו מוציאים להם צורת פעור ואומרים להם השתחוה לזה ותהיה נשמעת לו נמצא שמכשול עבודה זרה היה מהם, והוא אומרו **הן הנה** פירוש מדנפשם היו סיבה לבני ישראל, **בדבר בלעם** וגו' פי' באמצעות סיבת עצת בלעם שיעצם להפקיר בנותיהם לזנות, ותמצא שלא אמרו ז''ל שאמר בלעם אלא ענין הזנות כאומרם (שם) אלהיהן של אלו שונא זימה וכו' והם היו סיבה למסר מעל בה' על דבר פעור שלא היו רוצים להשמע להם אלא אם ישתחוו לפעור, **ותהי המגפה בעדת ה'** פירוש בסיבת עבודה זרה ולא בסיבת הזנות, ומי גרם עבודה זרה הן הנה, ואומר ועתה וגו' פירוש יתודו על השגגה ויהרגו וגו':
@33 **הרוגו**. הוצרך לומר פעם ב' הרוגו, אמר ר' ישמעאל (ספרי) להפסיק וכו', שאם לא כן יהיה מאמר וכל אשה וגו' שקול אם נמשך למעלה או למטה, וקשה שהיה לו להקדים תיבת החיו לכם בפסוק וכל הטף על זה הדרך החיו לכם, ובזה אין צורך לכפול מאמר הרוגו, ואולי שחש לומר כן שאז תהיה הכוונה שהוא מצווה אותם להחיותם, ולא כן מחשבת ה' אלא רשות הוא אומר שאין מצוה להמיתם, ולזה הקדים מאמר וכל הטף וגו' לומר שלא בא אלא להודיע מה יהיה דינם לא לצוות בהם:
@33 **ועוד** נשאר לנו ליישב מה שקשה עוד למה אמר **הרגו** בתחילת הכתוב ולא הספיק בהרוגו שאמר לבסוף, ואולי שנתכוון להסמיך מאמר הרגו למאמר ועתה לומר שהתשובה הרמוזה בועתה היא במעשה הריגה, וכל עוד שלא הרגו לא קיימו תשובת החטא, או אפשר שנתכוון להסמיך הרגו לטף והרוגו לאשה וכו' לומר שיש מצוה על אלו בפני עצמן ועל אלו בפני עצמן. או נתכוין להסמיך זכרון ההריגה לתיבת ועתה לומר שיהרגום תיכף ומיד:
@34 **החיו לכם**. פירוש יגיירו אותם שבזה יקראו חיים כדי שיהיו ראויות להם להנשא לחפץ בהם:
@48 (לב~מג) **ויהי המלקוח וגו' ותהי המחצה וגו' ויהי המכס וגו' ותהי מחצת וגו'**. צריך לדעת למה האריך כל כך בפרטי החשבון בדבר שיכול כל הבא למנות לידע כי כך יעלה למחצה וכן יעלה למכם וגו', גם בענין מחצת העדה לא האריך לומר כל פרטי הסכומים אלא חשבון העולה במחצית המלקוח וגם עליו דן אנכי שלא היה צריך לאומרו, והרמב''ן עליו השלום כתב טעם הדבר שבא להודיע שלא נחסר אחד מזמן המספר לזמן שחצוהו עד כאן, ואין נראה בעיני דבר זה שמה שלא נחסר מהמקנה בזמן מועט שיש בו נם, ומה גם שיצטרך הכתוב לכתוב כל הדברים בשבילו:
@48 **והנכון** בעיני הוא שהודעת פרטי החשבון במחצית חלק היוצאים בצבא הוא לגלות שהמכם היה מלגיו לא שהיה מונה חמש מאות ונותן אחד לה' מפאת המכם אלא מונה תצ''ט ונותן אחד, ולזה העלה כל פרטי חשבון המכם וממנו תדע שהיו נותנים א' לתצ''ט, והודעת חשבון מחצת העדה בא הכתוב להסיר טעות אחר והוא שיאמר האומר לעולם מכס שנתנו אנשי הצבא היה אחד מת''ק מלבר ואין ראיה מסכום המכס שעלה המכס לומר שאם כן לא היה עולה מכס של של''ז אלף וחמש מאות צאן למספר האמור יש לומר שהיו נותנים אותו המכס ממחצית העדה שבזה יעלה מספר האמור במכס חלק הצבא הגם שיהיה ניתן מלבר, אשר על כן בא הכתוב ומנה מספר חלק העדה ומנאו שלם להסיר מיחוש זה, ולזה לא פרט הכתוב במספר חלק העדה אלא מספר המחצית לצורך מה שכתבתי שהמכם ניתן מלגיו וכל אחד שילם חלקו ממחציתו, והוא גם כן מה שציוהו ה' במאמר ממחציתם תקחו לומר שלא יפרעו המכם אלא ממחציתם וגם אמר אחד מחמש מאות הא למדת שצריך שיהיה המכס מלגיו:
@65 (מט~נ) **ויאמרו אל משה וגו' ונקרב וגו'**. פירוש מאמר **ויאמרו** וגו' **ולא נפקד** וגו' הוא להסיר מהם חשש מכשול עון כמובן ממין הקרבן אשר הקריבו תכשיטי נשים, ומאמר **ונקרב** וגו' הוא טעם הקרבן שהוא לכפר על הרהור עון, כמאמרם ז''ל בשבת (סד.) ופירשתיהו בחיבורי (חפץ ה'):
@67 **כל כלי מעשה**. הודיע בזה ריבוי השלל של מדין לבד היה ששה עשר אלף ותש''נ, ואמר עוד **אנשי הצבא בזזו איש לו** אחר שכבר הודיע הכתוב למעלה ביזת אנשי הצבא שבזזו לעצמן, גם אין זה מקום הודעה זו, אלא בא להודיע כי לא כל כלי זהב של מדין היו אלו אלא מה שהביאו הממונים של הצבא מלבד מה שבזזו אנשי הצבא כל אחד לעצמו, והכוונה בזה שמצאו להם עושר גדול:
@70 **אל אהל מועד זכרון וגו' לפני ה'**. צריך לדעת למה כתב בסדר זה שהפסיק בין זכרון המקום ובין מאמר לפני ה' שהיה לו לומר אל אוהל מועד לפני ה' זכרון לבני ישראל, ויתבאר הכתוב על פי מה שאמרו במסכת כלה וזה לשונם אמר רב אחאי בר יאשיה כל המפנה עצמו מן העבירה אפילו הוא ישראל ראוי הוא להעלות עולה ככהן גדול על גבי המזבח וכו' עד כאן, ומה שלפנינו כל כלי מעשה שהרימו הפקודים היו מהאנשים שפינו עצמן מהעבירה והכלים באו מגוף הדבר, שאמרו ז''ל (שה''ש פסוק שיניד) שכך היה מנהגם באותה מלחמה כשהיו מפשיטים תכשיטיהם היו טחין פניהם בטיט ורפש והיו פורקין נזמיהם מהם שלא יסתכלו בהם, והוא מה שנתכוון במה שסמך מאמר לפני ה' למאמר לבני ישראל כי בני ישראל אלו ראוים להיות לפני ה' כמאמר רב אחאי בר יאשיה והיה הדבר לזכרון:
@71 **ומקנה רב וגו'**. טעם הודעה זו, להצדיק הכתוב טעם הנמצא בפיהם לשאלת ארץ סיחון ועוג כי אמת הוא, וטעם שהיה להם יותר מכל השבטים להיות שהיו גבורי כח בזזו אנשי הצבא חלק מרובה מכל השבטים:
@72 **ויאמרו אל משה ואל אלעזר הכהן ואל נשיאי העדה**. צריך לדעת למה לא הספיק להם לדבר למשה לבדו, ואם אין צורך בדבר למה הוצרך הכתוב להזכירם, ואולי שהכוונה היא לומר שהיה הדבר כדרך שצוה ה' עשות בנחלת הארץ, דכתיב בפרשת אלה מסעי (ל''ד י''ז) אלה אשר ינחלו לכם את הארץ אלעזר הכהן ויהושע בן נון ונשיא אחד נשיא אחד וגו' שצריך מלך וכהן גדול והנשיאים והם האמורים כאן, וטעם שהצריך ה' שלשתם לפי שכל אחד יש לו כח אחר, המלך תמצא שכתב רמב''ם בפרק ד' מהלכות מלכים וזה לשונו כל הארץ שכובש הוא שלו ונותן לעבדיו ולאנשי המלחמה כפי מה שיראה עד כאן, הרי שהמלך בידו הכל, אלעזר והנשיאים כשאין רצון המלך לתת אלא לכל אחד הראוי לו כפי החלוקה צריכין כל בעלי החלוקה להזדמן לחלוק, והכהן לדעת אשר יסכים אל עליון באיזה מקום יטול פלוני חלקו, הא למדת שכל הג' צריכין להיות בהסכמת נתינת חלק בארץ כל אחד יש לו כח אחר, ומה גם שיש בזה לצדד שאין דין מלך שנותן למי שירצה אלא אחר חלוקת הארץ וישיבת ישראל בעריהם אבל לא בתחילת הירושה שאין למלך משפט זה, ולכן הוצרכו בני גד ובני ראובן לעמוד גם כן לפני אלעזר והנשיאים, ואומרו **לאמר**, אולי ירצה שיאמרו לישראל כולן דבר שיסכימו עליו, או ירצה אמירה רכה לשון ריצוי:
@73 (ג~ד) **עטרות וגו' הארץ וגו'**. צריך לדעת א' למה הוצרכו לפרט כל העיירות ולא הספיק במאמר הכללי שאמרו הארץ אשר הכה ה' וגו' ששם כלולים כל הארצות ההם, או היה להם לומר כדרך שהזכירם הכתוב בסמוך בב' כללים דכתיב את ארץ יעזר ואת ארץ גלעד, ב' אומרו **הארץ אשר** וגו' וכי היו לפניהם ארצות אחרים ששמם כמו כן שהוצרכו לסמן אלו, ואם לומר שה' הכה אותם מי לא ידע בזה:
@73 **אכן** הכוונה היא על זה הדרך כי האנשים האלה השכילו לדבר בסדר שלא יהיה מקום להקשות לשאלתם מה שיש להקשות בענין. א' כיון שהארץ הלזו היא של כללות ישראל מה כוחם לשאול דבר של אחרים. ב' איך יעלה על דעתם שישבו בטח בארץ אשר כבר נכבשה ושאר השבטים יכנסו בסכנת המלחמות העצומות המוכנות להם, וכל אחד מישראל יאמר כדבריכם אדבר גם אני ולא אכנים עצמי בסכנת העמים, וכל זה למה שנוגע לשלילת הרצון ממשה וישראל, לבד מה שיש להתרעם עליהם שבוחרים לשבת חוץ לארץ הקדושה והנבחרת לה':
@73 **אשר** על כן נתחכמו בני גד ובני ראובן במאמר ראשון ונתנו תשובה לג' דברים הנזכרים המריעים שאלתם במה שאמרו **עטרות** וגו' **הארץ אשר הכה ה'** וגו', כנגד טענה א' שהארץ היא של כללות ישראל יש במאמר זה תשובה לזה שלא לקחו הארץ בדרך טבע לומר הלא לנו היא אלא ה' הוא שהכה יושביה לפניהם ואין זה אלא נכסי שמים ומנכסי גבוה אנו באים לשאול, גם טענה ב' שאחיהם יכנסו בסכנת מלחמות וכו' סתרוה במאמר זה **אשר הכה ה'** פירוש בשלמא אם ירושת הארץ היתה בדרך טבע היתה טענה זו טענה אבל כיון שה' הוא המכה את יושבי הארץ לפניהם מה מקום לחשש סכנת מלחמות, וזה לך האות הארץ אשר הכה ה' לפניהם, וזה סימן לכל הארץ דכתיב בפרשת דברים (ג' כ''א) ואת יהושע צויתי בעת ההיא לאמר עיניך הרואות את כל אשר עשה ה' אלהיכם לשני מלכי האמורי כן יעשה ה' לכל הממלכות אשר אתה עובר שמה, מעתה אין מקום לטענת פחד המלחמה, ונתכוונו גם כן בזה להסיר מיחוש הנופל בשאלתם שיאמרו שלא עשו כן אלא לפחד מלחמת הארץ:
@73 **גם** טענת מאיסת ארץ הקדושה נתנו תשובה במאמר **אשר הכה ה'** פירוש על דרך מה שכתב רמב''ם בפרק א' מהלכות תרומות וזה לשונו ארץ ישראל האמורה בכל מקום הוא ארץ שכבשה מלך ישראל או נביא מדעת רוב ישראל אבל יחיד מישראל או שבט שהלכו וכבשו לעצמן מקום אפילו מן הארץ שנתנה לאברהם אינה נקראת ארץ ישראל עד כאן, וכתב עוד שם בדין ארצות שכבש דוד וזה לשונו ומפני מה ירדו ממעלת ארץ ישראל מפני שכבש אותם קודם שיכבוש כל ארץ ישראל שנשאר בה מז' עממין עד כאן, ועיקר דין זה הובא בספרי (סוף פ' עקב) שלמדו דין שאר ארצות מארץ ישראל מפסוק (דברים י''א) כל מקום אשר תדרוך כף רגלכם בו לכם יהיה ללמד על מקומות שכיבשו חוץ מארץ ישראל שהוא מן המדבר והלבנון וגו' עד הים האחרון וגו', ולמדו שצריך להקדים ארץ ישראל מרכתיב קודם מאמר כל מקום וירשתם גוים גדולים וגו' שלא תהיה ארץ ישראל מטמאה בגילולים ואתם מכבשים חוצה לארץ וכו' עד כאן, הדברים יגידו שזולת טעם הקדימה כל שכבשוה רוב ישראל דין ארץ ישראל יש לה לכל דבר, והוא מאמר בני גד ובני ראובן **הארץ אשר הכה ה' לפני עדת ישראל** פירוש ארץ זו קדושת הארץ יש לה לטעם שכבשוה לפני עדת ישראל וכיבוש רבים דינה כארץ ישראל לכל דבריה:
@73 **ולטענת** מה שדייקו בספרי לומר שכיבוש חוץ לארץ קודם כיבוש הארץ אין לו דין ארץ ישראל ואם כן ארץ סיחון ועוג קודם כבישת הארץ היתה, לזה שללו טענה זו במאמר **אשר הכה ה'** פירוש משונה כיבוש זה לפי שהיה במאמר ה' כי הוא אמר אל משה על ארץ סיחון ואת ארצו החל רש כאמור בפרשת דברים (ב'), וגם על ארץ עוג (שם ג') אמר ה' שם בידך נתתי אותו ואת ארצו ואת כל עמו ועשית לו וגו', מעתה ה' הסכים על הקדימה, ויש גם כן טעם בדבר שלא היו לפניהם ב' כבישות אחד של הארץ ואחד של חוץ לארץ והקדימו של חוץ לארץ כדרך שעשה דוד שלקח ארם צובה קודם שהוריש היבוסי כאמור שם לומר למה הנחתם מלכבוש ארץ ישראל קודם, ואדרבה כבישת ארץ סיחון ועוג היתה צורך כיבוש הארץ כדי שיעברו דרך שם לכובשה, וכבר שלחו לו דברי שלום לתת להם מעבר דרך ארצו ולא אבה, מעתה אין תרעומת נגד שאלתם מה' ומישראל:
@73 **ובזה** יש טעם נכון למה הוצרכו להזכיר פרטי שמות הארץ, כי למה שנתכוונו במאמר אשר הכה ה' לומר שלא באו לשאול אלא מנכסי גבוה אמרו כי כל פרטי המדינות כלם לא כבשום דרך טבע אלא ה' הכה אותם לפניהם, בין למה שבאו להחזיקם בחזקת קדושת הארץ דקדקו להזכיר כל השמות לומר שכל אחת מהם ישנה בקדושת הארץ ומדינה אחרת זולת אלו אינה בכלל, והיוצא מזה כל עיר שבעבר הירדן זולת אלו אין להם דין ארץ ישראל לפי שאינה כיבוש רבים:
@73 **ואומרו ארץ מקנה היא ולעבדיך מקנה**, נתכוונו להסיר טענה אחרת והיא, אחר שנסכים לכל הטענות שאמרו עדיין כל שבט ושבט מישראל יבא ויאמר הטענות עצמן ליטול את הארץ כי הטענות עצמן צודקות לכל שבט מישראל, לזה אמרו אין שבט אחר צריך לה כמו שצריכין הם לה לפי שהיא ארץ מקנה ולהם יש מקנה רב:
@75 **ויאמרו וגו' יותן את הארץ וגו'**. הוצרך לומר תיבת **ויאמרו** הגם שהם עודם מדברים ולא היה הפסק לדבריהם, להעירך כי עד עתה היו מסדרים ההצעה שבאמצעותם תתקבל השאלה כדרך שפירשתי למעלה ומכאן הוא מתחיל מאמר השאלה, ואומרו **יותן** ולא אמרו תתן, לפי מה שפירשתי כי כח נחלת הארץ היא במלך וכהן וישראל לזה אמרו יותן פירוש תהיה הנתינה באופן המועיל, או אם ירצה לתת משה לבדו כמשפט המלך שיכול לתת כמו שכתבתי, או בהסכמת אלעזר והנשיאים כדין חלוקת הארץ:
@75 **אל תעבירנו את הירדן**. הכוונה בזה על דרך אומרם ז''ל (ב''ב קט:) בפסוק והעברתם את נחלתו לבתו שהבת מעברת הנחלה ממקומה, כמו כן נתכוונו לומר שאם לא יתן להם ארץ המקנה הראויה להם הנה הוא מעביר נחלתם ממקומ ה:
@75 **עוד** נתכוונו להרים מכשול החשד בהם שבוחרים בארץ זו לצד המנוחה לבל יכנסו לארץ אויביהם, ואמרו שטעם דבריהם אינו אלא לפי שאינם רוצים לנחול בעבר הירדן אלא כאן לצד ההכנה שיש להם ולא כדי שלא יטריחו במלחמות יושבי הארץ כי אין להם בזה אלא העברה:
@75 **עוד** נתכוונו במאמר **אל תעבירנו** לומר כי יש בזה דבר נאות לישראל שיקילו מעליהם עולם ולא יצטרכו לנחל אותם בארץ:
@75 **עוד** אפשר שנתכוונו לשלול העברתם עם ישראל כדרך שהתנה עליהם משה לבסוף, וסמכו על הטעם שנתנו בתחילת דבריהם שאמרו אשר הכה ה' ואין צורך לעבור כל חלוץ:
@76 **ויאמר משה וגו' האחיכם יבואו וגו' ולמה תניאון וגו'**. הן האדון משה רבינו השכיל בדברי בני גד ובני ראובן כל מה שרצו לומר כמו שפירשנו, וטען כנגד מה שאמרו שמנכסי גבוה הם שואלים כי העדה לא עשו דבר, גם מה שנתכוונו לטעון כנגד העתיד שאין טורח בדבר כי ה' הוא עושה נפלאות גדולות לבדו, אמר להם האחיכם יבואו למלחמה פירוש אמת כי ה' הוא הנלחם להם אבל על כל פנים צריכין להזדמן במלחמה, והוא מה שדייק **יבואו למלחמה** ולא אמר האחיכם ילחמו לומר שעל הביאה בלבד הוא תמה, ויש בזה סתירה על טענת מלחמה שעברה וגם טענת מלחמה הבאה בארץ שעל כל פנים כל איש ישראל יש להם יגיעה בדבר, ולמה יבקשו הם יגיע כפם של ישראל, וגמר אומר **ואתם תשבו פה**, נתחכם לומר שהגם שהבטחת ה' היא מושגת שאמירת הגבוה כמסירת הדיוט ואין כאן יגיעה, הלא תשכיל ביאת ישראל למלחמה בערך ישיבתכם פה ותראו כי יש הרגש ליגיעת ביאת המלחמה, ואם כן למה תרצו ליטול דבר שהיא יגיעה של ישראל כיון שאין אתם יגיעים עמהם בביאתכם למלחמת הארץ:
@76 **גם** נתכוון במאמר **תשבו פה** בטענה הנשמעת כי ארץ סיחון ועוג שהם שואלים נתנה ה' כשהיו מקובצים יחד שבטי ישראל שזכות כלן עמד להנחילם הארץ הלזו וכשהם נוטלים חלקם בארץ נגרע מערך זכות הרבים לפי שהם יושבים פה, ובזה סתר טענתם שנתכוונו במאמר אשר הכה ה' שזה יגיד על מלחמות הארץ שאין טורח לישראל כמו שפירשתי למעלה כי לא כן הוא שאין הדבר דומה:
@77 **ולמה תניאון וגו'**. פירוש מלבד הטענות עוד קובל אני עליכם למה תניאון את לב וגו', פירוש לו יהיה שאין כוונתכם אלא לטעמים האמורים בדבריכם, עם כל זה יש מקום לרוצה לחשוב שטענותיכם הוא ליראת עם הארץ, והגם שאתם שוללים הדברים שאדרבה אתם חושבים הארץ כאלו כבושה לפני ישראל, אפשר שזה עצה ותחבולה לכסות טעם הניכר שהוא ליראת יושבי הארץ, והן הנה דברי המרגלים שאמרו (י''ג ל''א) שחזק הוא ממנו, והוא אומרו כה עשו אבותיכם וגו', עוד נתכוון לומר להם שהיה להם לחוש לחשד זה אחר שכבר קדם מעשה האבות והיה מה שהיה שפחדו עם בני ישראל מעלות אל הארץ ולזה יש מקום לחשוב הדבר עצמו כשיראו שחלק מהשבטים מבקשים לשבת חוץ לארץ:
@77 **אשר נתז להם ה'**. נתכוון גם בזה כנגד מה שנתכוונו במאמר אשר הכה ה' וגו' לומר שדין הארץ יש לה, אמר להם שעל כל פנים יש הפרש בין הארץ אשר הם באים שמה מארץ אשר הם רוצים, כי הארץ נתן להם ה' מה שאין כן ארץ סיחון ועוג אינה בכלל ארץ שנתן ה' לאברהם, וכדתניא (ספרי ח''ב רצט) וזה לשונם לתת לך פרט לעבר הירדן שנטלת מעצמך, והגם שסברא זו סברת ר' שמעון אבל תנא קמא דורש דרשה אחרת, מדרבי שמעון נשמע לתנא קמא כי מן הסתם אינם חולקים בעיקר הדבר אם ארץ סיחון ועוג היא בכלל מה שנתן ה' לאברהם אם לאו:
@77 **גם** מצינו שאמרו רז''ל (במד''ר פ''ז) בעשר קדושות שאין עבר הירדן ראוי לבית המקדש ולשכון השכינה, וכן אמר הכתוב (יהושע כ''ב) אם טמאה ארץ אחוזתכם, הא למדת שיש הפרש בין ארץ סיחון ועוג לארץ ישראל, ואפשר כי מטעם זה לא היה בדעת משה לחלקה לשבטים והיה חפץ שיהיו כל ישראל בארץ אשר נתן ה' להם להיותה יותר קדושה, ועיין בפרשת דברים (ג' י''ג) בפסוק ההוא יקרא ארץ רפאים:
@86 **ויגשו וגו'**. טעם אומרו **ויגשו** הגם ששם היו עומדים לפניו לדבר אליו, אפשר שנהגו בעצמן הרחקה כשכעס עליהם משה ואמר להם קמתם תחת אבותיכם תרבות אנשים חטאים, לזה כשרצו לדבר אמר הכתוב ויגשו:
@86 **או** לפי שמדברי משה שתלה להם המניעה בדברים שבידם לתקנם לזה היה להם אבירות לב וחזקו ידים רפות לגשת אליו ביותר ממקום שהיו בו כשדברו אליו דברים הראשונים:
@86 **גדרות צאן וגו'**. קשה למה הוצרכו למאמר זה של גדרות צאן וגו' שלא היה להם לומר אלא תשובה הסותרת השגותיו של משה האמורה בדבריהם בסמוך שהוא אנחנו נחלץ חושים וגו' לא נשוב וגו' עד התנחל, ויתבאר על פי מה שכתב רמב''ם בפרק י''א מהלכות מכירה וזה לשונו המוכר בית לחבירו או נתנו לו במתנה על מנת שילך עמו לירושלים ביום פלוני והחזיק זה בבית קנה כשילך עמו לירושלים באותו יום, אבל אם התנה ואמר לו אם תלך עמי לירושלים ביום פלוני אתן לך בית זה וכו' והלך עמו באותו היום אף על פי שהחזיק בבית אחר שקיים התנאי לא קנה שזה אסמכתא עד כאן, ובפרק א' מהלכות מכירה כתב וזה לשונו כיצד החזקה מכר לו בית מכר לו שדה או שנתן וכו' כיון שנעל או פרץ או גדר כל שהוא והוא שיועיל מעשיו הרי זה קנה עד כאן לשונו:
@86 **ועל** פי הדינים נתחכמו בני גד ובני ראובן לדבר דבריהם כיון שמה שלפניהם הוא הדבר בתנאי במציאות עצמו שכתב רמב''ם בפרק י''א מהלכות מכירה שהם מקבלים הארץ בתנאי שיעלו עמהם לארץ ישראל, ולזה הקדימו זכיתם בארץ קודם התנאי שהוא מציאות שכתב בו רמב''ם, ואמרו **גדרות צאן נבנה** וגו' פירוש נחזיק בארץ לזכותינו מעכשיו ותנאי הוא הדבר על מנת שנעלה לארץ עם אחינו ביום שיעלו, ואמרו אופן החזקה **גדרות צאן** וגו' נתכוונו לעשות החזקה בכל המקומות במה שיעשו בו גדרות לצאן וערים לטף פירוש יבנו בדרך שיועילו מעשיהם בארצות כמשפט החזקה:
@86 **ואם** תאמר למה הוצרכו לומר הדברים והיו יכולין להחזיק מעצמן באין צורך הודעה, הנה כתב רמב''ם בפרק א' מהלכות מכירה וזה לשונו במה דברים אמורים שהחזיק בפני המוכר או הנותן אבל שלא בפני המוכר וכו' צריך שיאמר לו לך חזק וקני ואחר כך אם החזיק קנה אף על פי שהוא שלא בפני הבעלים עד כאן, ולזה נתכוונו כאן לומר ענין החזקה לפניהם כדי שיסכימו שזולת זה אין חזקתם חזקה, ולזה כשהסכים משה על הדבר אמר להם **בנו לכם ערים** וגו', והוא מה שכתב רמב''ם שאמר לו לך חזק וקני:
@86 **ולסברת** רמב''ן וסיעתו שחולקים עם הרמב''ם בדין זה וסוברים שכל שהתנאי קיומו תלוי ביד הלוקח או המקבל מתנה אין בו דין אסמכתא משום שהמקנה גמר והקנה, כפי זה צריך ליישב טעם מאמר בנין הגדרות וערים כי הוא לבל יתחייבו לעבור הירדן עד שיכינו הגדרות ויבנו הערים ואז יחלצו ללכת עמהם, והוא אומרו גדרות צאן נבנה למקננו וערים לטפנו ואחר כך אנחנו נחלץ חושים וגו':
@87 **וישב טפנו וגו'**. הוצרך לומר זה, גם לא אמרו כן למעלה כשהזכירו וערים לטפנו, נתכוונו לומר שאם ישבו טפם בערים בצורות אז יכולין להוסיף עוד תנאי אחר שלא ישובו לבניהם עד התנחל איש נחלתו פירוש אחר שיעברו שבע שנים של כיבוש ושבע שנים של חילוק, ואם לא יהיו בערי המבצר פירוש ערים בצורות אלא לשמירה כמצטרך לא יהיו בטוחים בהם להתעכב כל כך ארבע עשרה שנה אלא שבע שנים עד שיכבשו את הארץ, ולזה כתב מאמר וישב טפנו בערי המבצר באמצע שני המאמרים שכולם ענין אחד שהם מאמר ואנחנו נחלץ חושים וגו' עד הביאונום אל מקומם ומאמר לא נשוב אל בתינו עד התנחל וגו' ומן הראוי היה לו להסמיך שני המאמרים שהשני גזרה של הראשון ולא להפסיק בשלא כענין, ולדרכנו יתישב על נכון:
@87 **גם** יתישב למה אמרו ב' גבולים נגדיים, א' עד אשר אם הביאונום וגו, ' וב' עד התנחל, והגם שהא' אמרו לענין נחלץ חושים והב' לענין השבתם לארצם, עם כל זה מפסוק ראשון משמע שלא חייבו עצמן אלא עד הביאם למקומן ולא עד התנחל, ולדברינו עלה על נכון, ואמר להם משה בנו לכם ערים לטפכם, דקדק לומר **לכם**, פירוש למה שברצונכם שהוא לבנות ערי מבצר, וכן היה דכתיב ויבנו את דיבון ואת עטרות וגו' שאלו הם ערי המבצר שהם העיירות הגדולות שהזכירו בשאלתם, ותמצא שלא חזרו לבתיהם עד אחר י''ד שנה של כיבוש וחילוק:
@89 **כי לא ננחל וגו' כי באה וגו'**. אומרו כי **לא ננחל**, הוא נתינת טעם למה שאמרו בסמוך עד התנחל בני ישראל וגו' שהוציאו עצמן מהנחלה לזה אמרו טעם שאנו מיחסים הנחלה לישראל ולא לנו מטעם כי לא ננחל אתם כי באה וגו' פירוש מטעם שבאה נחלתנו וגו'. או נתכוונו לומר שאחר שקבלו עליהם כל האמור יודע עתה שטעם שאלתם לא מטעם יראתם ממלחמת העמים הוא כמו שבא החשד בדברי משה אלא מטעם שאין להם נחלה בארץ כי ה' נתן להם נחלתם כבר מעבר הירדן מזרחה:
@90 **ויאמר אליהם משה אם תעשון וגו' אם תחלצו וגו'**. קשה למה כפל לומר **אם תעשון** וגו' **אם תחלצו** וגו' ולא הספיק באחת מהנה, ולכשנדייק לא היה צריך להשיבם אלא יסכים לדבריהם במה שיקרא ליהושע ולאלעזר ויצו אותם כאמור בסמוך, עוד למה דקדק לומר הזה, עוד מה כוונתו באומרו בסמוך לפני ה':
@90 **אכן** כוונת מאמר משה היא לפי שראה שדעת בני גד ובני ראובן שרוצים לעבור עם ישראל אינו אלא כדי שיתרצו ויחליטו להם נתינת הארצות ולא לתכלית אחר, ודבר זה אין נכון לעשות כן לענין הצלחת המלחמה כי צריכין בני המלחמה שתהיה מלחמתם להנקם מאויבי ה' להכרית להם כל נשמה ותקרא מלחמת חובת מצות ה', וזה לך לשון רמב''ם בפרק ז' מהלכות מלכים כל הנלחם בכל לבו וכו' ותהיה כוונתו לקדש ה' בלבד מובטח לו שלא ימצא לו שום נזק ולא תגיעהו רעה וכו' ויזכה לחיי עולם הבא עד כאן:
@90 **על** כן האנשים ההמה כיון שאין הולכים אלא להתקיים בידם הארץ יש מיחוש בחליצתם שלא תועיל, ואפשר שיהיו ניזוקים מהם, אשר על כן נתחכם משה ואמר להם **אם תעשון** וגו' **אם תחלצו** וגו', פירוש כנגד מה שאמרו הם ואנחנו נחלץ חושים וגו' אמר אם תעשון את הדבר הזה, ותיבת זה חוזרת למאמר הנאמר בסמוך, וכנגד מה שכוונתן בהליכה לקיום התנאי אמר אם תחלצו לפני ה' למלחמה, דקדק לומר **לפני ה'** כמאמר רמב''ם שכתב שתהיה כוונתו לקדש ה', וכמו שגמר אומר **עד הורישו את אויביו** פירוש אויביו של הקדוש ברוך הוא, ואין לפרש אויביו של ישראל שהרי לא הוזכר בדברי משה מתחילת דבריו עד עתה זכרון ישראל לומר שעליו חוזר מאמר אויביו, אלא ודאי כי לה' חוזרים הדברים שתהיה כוונתם להנקם מאויבי ה' לקדש שמו יתברך, וכפירוש זה הרווחנו גזרת דברי משה שלא נודע מקומה שכל המאמרים הטיל להם וא''ו בתחילתה, ולדברינו הגזרה היא לפני ה':
@90 **עוד** נתכוון באומרו **אם תחלצו לפני ה'** להשיבם להמובן בדבריהם שאמרו נחלץ וגו' לפני בני ישראל שזה יגיד שישראל צריכין עזר טבעי, לזה אמר אם תחלצו לפני ה' תחלצו פירוש להרבות זכותכם לפני ה' שאין דומה זכות מאה לזכות מאה ואחד:
@91 **ועבר לכם כל חלוץ**. ולא הספיק מה שאמר אם תחלצו, בא להתנות דבר שלא הוזכרו בדבריהם והוא שיעברו כולם פירוש כל הראוי לחלוץ צבא, אלא שעדיין קשה שהיה לו לומר בפסוק ראשון אם תחלצו כולכם או אם תעברו כולכם חלוצים:
@91 **אכן** כוונת משה בזה הוא הבטחה והודעת דיוק הנשמע על זה הדרך שאם **תעשו** וגו' **ותחלצו** וגו' מבטיח כי לא יפול מהם אחד ויהיו שלמים וכן רבים, והוא אומרו **ועבר לכם כל חלוץ** פירוש כולם ולא יפקד מהם איש, ומכלל זה אתה שומע שאם לא יעשו האמור הם מוכנים להשחתה, וכפירוש זה מאמר **ועבר** וגו' הוא גזירה לפסוק שקדם לא תנאי במעשה שהתנאי כבר אמר אם תעשון הדבר הזה שפירושו הוא התנאי שהתנו הם כמו שכתבתי למעלה, ואומרו **לפני ה'** לומר שבזה לא יהיה מסך מבדיל בינם ובין ה' כאומרו (ישעי' נט) עונותיכם היו מבדילין ביניכם לבין אלהיכם, שס''מ הרשע וחילותיו הם המבדילים והם המכלים:
@91 **עוד** נתכוון לומר **לפני ה'** פירוש שהוא המוריש אויביו כמו שגמר אומר עד הורישו פירוש ה' לאויביו מפניו, וכפירוש זה שיעור הכתוב הוא על זה הדרך **אם תחלצו** ותהיה כוונתכם לפני ה' וגו' אז אינכם צריכין למלחמה אלא העברה לבד לפני ה' והוא יוריש אויביו, והוא אומרו ועבר לכם וגו' לפני ה' היוצא להנקם עד הורישו אויביו הא למדת כי הוא המוריש לפני בני ישראל, ודקדק לומר **מפניו**, לפי שה' שוכן בעיר אשר בחר לו ירושלים החביבה ואינו חפץ לראות אויביו לפניו:
@92 **ונכבשה הארץ**. צריך לדעת למה לא הספיק במאמר עד הורישו שאמר בסמוך, עוד צריך לדעת למה הוצרך לומר **ואחר תשובו** שמובן הוא מאומרו עד הורישו וגו' הרי גבול ההליכה ומובן מעצמו שישובו אחר כך. אכן כוונת משה בזה הוא הבטחת הטובה הנמשכת מקיום הדברים, כי באמצעות מעשה הקודם יובטחו בכמה הבטחות, א' **ונכבשה הארץ** פירוש ודאי שתכבש הארץ לפני ה', ב' **ואחר תשובו** פירוש הבטיח כל המדבר אליהם שלא יפקדו בכל זמן שיהיו בארץ במלחמות הגדולות וישובו שלימים לביתם, והגם שמצינו (ב''ב קכא:) שיאיר בן מנשה נהרג במלחמת העי, חצי המנשה לא היה מאותם שדבר משה עמהם אז כמובן מהכתובים:
@92 **עוד** הודיעם שבזה יהיו נקיים מה' ומישראל, פירוש מה' כשיעברו למלחמה על דרך שכתבתי שתהיה כוונתם לקדש שם שמים ולא להנאתם בשביל קיום תנאי הארץ, ומישראל לבל יחשדו שטינא היתה בלבם מהמרגלים כמו שאמר להם משה קמתם תחת אבותיכם תרבות אנשים חטאים שכוונתם לשוב מאחרי ה', ואומרו **והיתה הארץ** וגו' הבטיחם שבזה תתקיים בידם הארץ לאחוזה ולא תהיה נגזלת מהם, וממוצא דבר אתה למד שאם לא יעשו כדבר משה יושללו מכל הבטחות הטובות:
@92 **ואומרו לפני ה'** אפשר שנתכוון להחזיקם בקדושת הארץ מהטעמים עצמן שאמרו הם בתחילת דבריהם, וזה הוא שיעור דבריו **והיתה הארץ הזאת** וגו' הגם שהוא חוצה לארץ תהיה נחשבת לכם **לאחוזה לפני ה'** פירוש תהיה נחשבת אחוזה זו שהיא לפני ה' וזו היא קדושתה שלטעם זה היא שנחשבת הארץ קדושה לפי שהיא לפני ה' באין רצועת חול מפסקת בינה ובין ה' שוכן הבירה:
@93 **ואם לא תעשון כן הנה חטאתם**. קשה לא היה לו לומר אלא ואם לא תעשון כן לא תהיה הארץ הזאת לכם. אכן כוונת המאמר הוא שאם לא יעשו כדברי משה שצוה אותם שילכו לקיים מצות מלחמת חובה לעשות נקמה באויבי ה' הגם שיעברו חלוצים הנה חטאתם פירוש מה שלפנינו כבר יש בידכם חטא, והוא מה שדקדק לומר חטאתם לה' כבר:
@93 **ודעו את חטאתכם וגו'**. פירוש מודיעם שמי שיש חטא בידו ימצאהו בשעת הסכנה ויפרע ממנו, והוא אומרו **אשר תמצא אתכם** בפשיטות, וצא ולמד ממאמרם ז''ל (טוש''ע או''ח סי' נד) שחוזרים מעורכי המלחמה על חטא קל אם שח בין ישתבח ליוצר, וכמו כן ימצאם עון זה ויחסרו כל ההצלחות הרשומים בדבריו, גם אז לא יהיו נקיים מה' ומישראל כי מהמקרה הרע אדרבה יצדיקו כי לא נקיים היו, ועיין מה שפרשתי בתשובת בני גד ובני ראובן שאמרו עבדיך יעשו כאשר אדוני מצוה:
@94 **והיוצא מפיכם תעשו**. הכוונה במאמר זה שלא יבינו שהחליט להם מאמר בנין הערים וגו' על כל פנים אלא תנאי הוא הדבר. או נתכוון להשיב למה שאמרו שאם יבנו ערי מבצר וישבו שם טפם שיתעכבו עד שינחלו ישראל נחלתם בארץ, לזה אמר **והיוצא** וגו' פירוש פרט זה אם לא הייתם אומרים אותו אין צורך בו למיחוש שיש בענין והיה די בעכבתכם שם עד תשלום שבע שני כיבוש ואין צורך להתעכב שם ארבע עשרה שנה, ולפי שאתם אמרתם כן היוצא מפיכם תעשו, ותמצא שלא התנה עליהם משה אלא עד שנכבשה ולא עד שנחלקה כאמור במאמר התנאים לומר שאין תנאי זה מעכב אלא לקיים היוצא מפיהם:
@95 **ויאמר בני גד וגו' לאמר עבדיך יעשו וגו'**. קשה א' אומרו **לאמר** למי יאמר משה, ב' מה חידוש בדבריהם **עבדיך יעשו** הלא כבר הם קדמו ואמרו מה שצוה אותם משה, ג' אחר שאמרו בדרך כלל עבדיך יעשו כאשר אדוני מצוה למה הוצרכו לומר עוד **טפנו** וגו' **יהיו שם** וגו' **ועבדיך יעברו**, עוד למה כפלו לומר **כאשר אדוני דובר** והלא כבר אמרו עבדיך יעשו כאשר אדוני מצוה, ד' למה שינה בפסוק ראשון אמר **מצוה** ובפסוק ב' אמר **דובר**:
@95 **אכן** לפי מה שפירשתי בדברי משה שנתכוון לחדש להם שתהיה כוונת עברתם למלחמה כמשפט אוהבי שמו כמו שכתב רמב''ם בפרק ז' מהלכות מלכים, גם בענין פרט הקדמת ערים לטף לבנין גדרות צאן כאומרם ז''ל (מד''ר כאן) שהם חבבו הממון מטף ומשה הפך להם, לזה השיבו יחד כאיש אחד ויאמר בני גד והסכימו למאמר משה בב' הפרטים שחדש להם משה, והתחילו מהסמוך שהוא ענין חיבוב טפם מממונם ואמרו **טפנו** וגו' **וכל בהמתנו** הרי שהקדימו טפם לבהמתם כדברי משה, ואחר כך אמרו גם כן הודאתם עשות בפרט הראשון שתהיה כוונתם במלחמה לפני ה', והוא אומרם ועבדיך יעברו כל חלוץ צבא לפני ה' כאשר אדוני דובר ולא כמו שאמרו בתחילה נחלץ חושים לפני בני ישראל עד הביאונום וגו':
@95 **והנה** לצד כי ב' דברים אלו יש עליהם חיוב לקיימם בשביל שכך התנה עליהם משה וכל תנאי שבממון קיים הגם שיהיה המתנה איש הדיוט, לזה נתחכמו בתחילת דבריהם ואמרו כי גם בלא חיוב התנאי עליהם לקיים כל דברי משה נביא ה' דכתיב (דברים יח) אליו תשמעון, והוא מה שנתכוונו במאמר ראשון שאמרו **עבדיך יעשו כאשר אדוני מצוה** אותנו לעשות גם בלא טעם שהוא תנאי נתינת הארץ, ולזה אמר תיבת **לאמר** פירוש במאמרך לבד חובה עלינו לעשות מצותך:
@95 **גם** ירצה לשון עילוי ורוממות כי דבר זה אמרוהו בני גד ובני ראובן לצד מעלת מלך ונביא, ואחר כך פירשו הדברים ואמרו **עבדיך יעשו כאשר אדוני דובר** פירוש גם מלבד חיוב הבא מחמת המצוה יש חובה עלינו לעשות הגם שלא היה הדבר מצוה אלא דיבור כדברים העוברים בין אדם לחבירו בעניני תנאי מקח וממכר זוכה ומזכה בעניני העולם, והכוונה בזה שמקבלים גם כן עליהם הדבר כדברים שמתחייב אדם לחבירו בתנאי הממון שקיימין כראי מ וצק:
@99 **ויאמר משה וגו' ונתתם להם**. אמר ונתתם להם שנראה כי הם הנותנים ובסמוך אמר הכתוב ויתן להם משה וגו' את ממלכת וגו', לפי שאין החלט הנתינה אלא אחר קיום התנאי לזה אמר ונתתם, ונשאר לדעת למה אמר **ונתתם** שהיה לו לומר תתנו להם, ואולי שרמז להם הדברים עצמן שאמר לבני גד ובני ראובן שאם ילכו יצליחו כל ישראל בין הנוחלים בארץ בין הנוחלים בעבר הירדן, והוא אומרו **אם יעברו** וגו' **ונכבשה** וגו' הצלחת נוחלי הארץ, **ונתתם** וגו' הצלחת נוחלי עבר הירדן, ורמז זה לא היה נשמע אם היה אומר תתנו להם:
@100 **ואם לא יעברו חלוצים אתכם**. פירוש הגם שיעברו אחר כך יאחזו בתוככם, וטעם אומרו **ונאחזו** בתוספת וא''ו ולא אמר יאחזו, נתכוון לרמוז דיוק הצלחתם הנשמע מפסוק אם יעברו על זה הדרך ואם לא יעברו אין הצלחתם בארץ הלזו ומעצמן יאחזו בתוככם לצד המצר להם בארץ, ונמצאו בטלו המצוה ושלהם לא הגיעם:
@101 **ויענו בני גד וגו'**. הוצרכו להחזיר הדברים, גם אמר הכתוב **ויענו** ולא אמר ויאמרו, לפי שאמר משה ונתתם להם חשו שאז תתחיל הנתינה לזה ענו ואמרו כי עברתם חלוצים הוא דבר שחייבן לעשותו בדבר מלך שלטון ומלחמת חובה היא להם, והוא אומרו **את אשר דבר ה' לעבדיך כן נעשה** נחנו נחלץ חושים לפני ה' להלחם באויביו, אבל הנתינה היא מעכשיו, והוא אומרו **ואתנו אחו זת נחלתינו**, והם לא הבינו כוונת דברי משה כמו שפירשנוהו, ולזה תכף נתן להם ובזה גילה דעתו כי כוונתו במאמר ונתתם להם היא בידם כמו שפירשתי:
@101 **או** אפשר שגם משה דעתו היה שלא יתחיל זכותם בה אלא אחר התנאי וכשראה חוזק רצונם במעשה הטוב הסכים ונתנה להם תכף ומיד:
@101 **חסלת פרשת מטות**
